INSERT INTO `hoaks` (`id`, `judul`, `slug`, `penulis`, `kategori_id`, `status`, `berita`, `source`, `image`, `deskripsi`, `created_at`, `updated_at`) VALUES
	(1, '[PENIPUAN] Tautan “Pendaftaran Peserta JKN Gratis Seumur Hidup”', 'penipuan-tautan-pendaftaran-peserta-jkn-gratis-seumur-hidup', 'Pemeriksa Fakta Junior', 7, 'verified', 'nasional', 'https://turnbackhoax.id/2025/05/16/penipuan-tautan-pendaftaran-peserta-jkn-gratis-seumur-hidup/', 'https://turnbackhoax.id/wp-content/uploads/2025/05/HEADER-Light-Background-2-326x245.png', '<ul><li>Faktanya, tidak ada program “JKN Gratis Seumur Hidup”.</li><li>Unggahan berisi tautan “pendaftaran JKN gratis seumur hidup” merupakan konten tiruan (impostor content).</li></ul><p>Pada Rabu (14/5/2025) akun Facebook “Bantuan BPJS terbaru gratis 2025” membagikan <a href="https://www.facebook.com/permalink.php?story_fbid=122097627716876030&amp;id=61576280908756"><span style="text-decoration: underline;">tautan</span></a> [<a href="https://turnbackhoax.id/wp-content/uploads/2025/05/JKN.jpeg"><span style="text-decoration: underline;">arsip</span></a>] disertai narasi :</p><p>“𝗔𝗹𝗵𝗮𝗺𝗱𝘂𝗹𝗶𝗹𝗮𝗵 𝗺𝘂𝗹𝗮𝗶 𝗵𝗮𝗿𝗶 𝗶𝗻𝗶 𝘀𝗲𝗺𝘂𝗮 𝘁𝘂𝗻𝗴𝗴𝗮𝗸𝗮𝗻 𝗕𝗣𝗝𝗦 𝗱𝗶𝗵𝗮𝗽𝘂𝘀𝗸𝗮𝗻 𝗱𝗮𝗻 𝗯𝗶𝘀𝗮 𝗯𝗲𝗿𝗮𝗹𝗶𝗵 𝗸𝗲 𝗕𝗣𝗝𝗦 𝗚𝗿𝗮𝘁𝗶𝘀, 𝗣𝗿𝗼𝗴𝗿𝗮𝗺 𝗽𝗲𝗺𝗲𝗿𝗶𝗻𝘁𝗮𝗵 𝘀𝗲𝗺𝘂𝗮 𝗕𝗣𝗝𝗦 𝗱𝗶𝘁𝗮𝗵𝘂𝗻 𝟮𝟬𝟮𝟱 𝗚𝗿𝗮𝘁𝗶𝘀.𝗦𝗮𝗮𝘁𝗻𝘆𝗮 𝗯𝗲𝗿𝗮𝗹𝗶𝗵 𝗱𝗮𝗿𝗶 𝗕𝗣𝗝𝗦 𝗠𝗮𝗻𝗱𝗶𝗿𝗶 𝗸𝗲 𝗕𝗣𝗝𝗦 𝗚𝗿𝗮𝘁𝗶𝘀.𝗨𝗻𝘁𝘂𝗸 𝗱𝗮𝗳𝘁𝗮𝗿 𝗼𝗻𝗹𝗶𝗻𝗲 𝗕𝗣𝗝𝗦 𝗚𝗿𝗮𝘁𝗶𝘀 𝗸𝗹𝗶𝗸&nbsp; 𝗱𝗮𝗳𝘁𝗮𝗿 𝗱𝗶𝗯𝗮𝘄𝗮𝗵.”</p><p><figure data-trix-attachment="{&quot;contentType&quot;:&quot;image&quot;,&quot;height&quot;:351,&quot;url&quot;:&quot;https://lh7-rt.googleusercontent.com/docsz/AD_4nXcm5AKw1qpf5A49NHc5Iy8P7kGypRItwuRlEOviRvIAgAC-q_k90Ta6ty0qYscF5G-dsVF6jN_7ZERmB9jI3N6JCZyv5iEL1Z1CGdG1TCsox0Ug61WtitsD_WorgGhKXIXfQCHv7w?key=MY0bPy95wFvQYQuoCbKsFw&quot;,&quot;width&quot;:624}" data-trix-content-type="image" class="attachment attachment--preview"><img src="https://lh7-rt.googleusercontent.com/docsz/AD_4nXcm5AKw1qpf5A49NHc5Iy8P7kGypRItwuRlEOviRvIAgAC-q_k90Ta6ty0qYscF5G-dsVF6jN_7ZERmB9jI3N6JCZyv5iEL1Z1CGdG1TCsox0Ug61WtitsD_WorgGhKXIXfQCHv7w?key=MY0bPy95wFvQYQuoCbKsFw" width="624" height="351"><figcaption class="attachment__caption"></figcaption></figure></p><p>Hingga Jumat (16/5/25), unggahan telah mendapatkan 6 tanda suka.</p><p><strong>Pemeriksaan Fakta</strong></p><p>Disadur dari artikel Cek Fakta <a href="https://www.kompas.com/cekfakta/read/2025/05/05/121800182/-hoaks-tautan-pendaftaran-peserta-jkn-gratis-seumur-hidup"><span style="text-decoration: underline;">kompas.com</span></a></p><p>Tim Cek Fakta Kompas.com menghubungi Kepala Humas BPJS Kesehatan Rizzky Anugerah untuk mengonfirmasi kebenaran narasi tersebut. Rizzky menegaskan klaim dan tautan yang beredar adalah hoaks dan merupakan modus penipuan.</p><p>“Tidak ada bantuan dan program seperti hal tersebut. Masyarakat agar berhati-hati terhadap penipuan mengatasnamakan BPJS Kesehatan,” kata Rizzky kepada kompas.com, Sabtu (3/5/2025).</p><p>Ia mengimbau masyarakat untuk menghubungi saluran komunikasi resmi apabila memiliki pertanyaan atau keluhan terkait BPJS Kesehatan.</p><p>Berikut saluran komunikasi resmi BPJS Kesehatan:</p><ul><li>Care Center 165</li><li>Aplikasi Mobile JKN</li><li>Pandawa (Pelayanan Melalui WA) di nomor 08118165165</li></ul><p><strong>Kesimpulan</strong></p><p>Unggahan berisi tautan “pendaftaran JKN gratis seumur hidup” merupakan konten tiruan (impostor content).</p><p><strong>(</strong><strong><em>Ditulis oleh Raymondha Elsha</em></strong><strong>)</strong></p>', '2025-05-17 00:16:33', '2025-05-18 20:42:21'),
	(2, '[SALAH] Ibadah Sambil Joget', 'salah-ibadah-sambil-joget', 'Aribowo Sasmito', 4, 'verified', 'nasional', 'https://turnbackhoax.id/2025/05/16/salah-ibadah-sambil-joget/', 'https://turnbackhoax.id/wp-content/uploads/2025/05/ratik-tagak-HEADER-326x245.png', '<ul><li>Faktanya, video yang dibagikan adalah rekaman Ratik Tagak, tradisi budaya dari Minang. Tidak termasuk kegiatan ibadah karena dilakukan setelah salat, zikir, dan doa selesai dilaksanakan.</li><li>Unggahan yang membagikan video tersebut masuk ke kategori konten yang menyesatkan (<em>misleading content</em>).</li></ul><p>Pada Rabu (16/4/2025) beredar <a href="https://x.com/ProfOnline_id/status/1912306690277707887"><span style="text-decoration: underline;">unggahan</span></a> di X (<a href="https://archive.ph/nh1ZE"><span style="text-decoration: underline;">arsip cadangan</span></a>) yang membagikan sebuah video dengan narasi:&nbsp;</p><blockquote>“Menyapa kawan kawan dunia maya kecuali orang orang Islam Sunni yang ibadahnya lagi niru cara ibadah orang orang Kristen yang sambil joged joged di Gereja.Kata nabi Islam: siapa yang meniru suatu kaum maka kafirlah dia….”.&nbsp;</blockquote><p>Per tangkapan layar dibuat pada Kamis (15/5/2025) unggahan tersebut telah ditonton 7,771 ribu kali, mendapatkan jawaban 40 kali, dibagikan 28 kali, dan disukai 119 kali oleh pengguna X lainnya.</p><p><strong>Pemeriksaan Fakta</strong></p><p>Karena sudah pernah membuat artikel periksa fakta sebelumnya, Tim Pemeriksa Fakta MAFINDO (TurnBackHoax) menelusuri kebenaran klaim menggunakan fitur pencarian di situs turnbackhoax.id yang menghasilkan 3 artikel yang sudah pernah dipublikasikan sebelumnya yaitu pada 2018, 2019 dan 2022, yang artinya unggahan ini termasuk HDU/HLBK (Hoaks Daur Ulang/Hoaks Lama Bersemi Kembali.&nbsp;</p><p>Faktanya, bukan beribadah sambil berjoget. Video yang dibagikan adalah rekaman Ratik Tagak, tradisi budaya dari Minang yang tidak termasuk kegiatan ibadah karena dilakukan setelah salat, zikir, dan doa selesai dilaksanakan.&nbsp;</p><p>Selain itu, pada tahun 2018 lalu Ratik Tagak sudah ditetapkan UNESCO sebagai salah satu warisan budaya tak benda Indonesia.</p><p><strong>Kesimpulan</strong></p><p>Unggahan tersebut masuk ke kategori konten yang menyesatkan (<em>misleading content</em>), faktanya video yang dibagikan adalah rekaman Ratik Tagak, tradisi budaya dari Minang yang tidak termasuk kegiatan ibadah karena dilakukan setelah salat, zikir, dan doa selesai dilaksanakan.&nbsp;</p>', '2025-05-17 00:16:35', '2025-05-18 20:41:48'),
	(3, '[SALAH] Video “Truk Nekat Terobos dan Tabrak Tarub Resepsi”', 'salah-video-truk-nekat-terobos-dan-tabrak-tarub-resepsi', 'Tim Kalimasada', 1, 'verified', 'nasional', 'https://turnbackhoax.id/2025/05/16/salah-video-truk-nekat-terobos-dan-tabrak-tarub-resepsi/', 'https://turnbackhoax.id/wp-content/uploads/2025/05/WhatsApp-Image-2025-05-16-at-19.00.44-326x245.jpeg', '\n\n\n<ul class="wp-block-list">\n<li>Bukan penutupan jalan untuk resepsi, aksi blokade tersebut dilakukan warga lantaran jalan rusak akibat pengangkutan material berat atau curah dengan dump truk di pertambangan.</li>\n\n\n\n<li>Unggahan “video truk nekat terobos dan tabrak tarub” merupakan konten yang menyesatkan (misleading content).</li>\n</ul>\n\n\n\n<hr class="wp-block-separator has-alpha-channel-opacity">\n\n\n\n<p>Beredar sebuah unggahan <a href="https://www.instagram.com/reel/DIGhfB5P4VY/?igsh=MXF3Z3Y0bzNlZHF6OQ%3D%3D">video</a> [<a href="https://archive.ph/AQCrJ">arsip</a>] oleh akun Instagram “yantidarrel” pada Minggu (6/4/2025). Video tersebut menunjukkan sejumlah truk tampak menerobos jalan yang diduga ditutup oleh warga untuk acara resepsi. Warga yang ada di lokasi pun terlihat berusaha menghentikan laju kendaraan. Akan tetapi sopir truk tampak tetap terus melaju kendaraanya hingga terdengar suara remuk pada kursi yang ditabraknya.&nbsp;</p>\n\n\n\n\n\n\n\n<p>Hingga artikel ini ditulis, unggahan tersebut telah diputar sebanyak lebih dari 2 juta kali, disukai lebih dari 145 ribu kali, dan menuai lebih dari 1.500 komentar.</p>\n\n\n\n<p><span style="background-color: #ff8c00;padding: 3px 8px;font-weight: bold;border-radius: 8px">Pemeriksaan Fakta</span></p>\n\n\n\n<p>Tim Pemeriksa Fakta Mafindo (TurnBackHoax) coba melakukan penelusuran sumber tersebut melalui alat pencarian “InVid” dengan <em>Google.</em> Hasilnya, ditemukan sebuah unggahan serupa oleh akun TikTok “<a href="https://www.tiktok.com/@radar_update/video/7317515194270272773?_r=1&amp;_t=ZS-8wIEG0xYQvn">Radar_update</a>”</p>\n\n\n\n<p>Dalam keterangannya, peristiwa tersebut dilakukan oleh sopir truk batu bara yang nekat menerobos blokade warga di Batu Kajang, Kabupaten Paser, Rabu (27/12/2023). Aksi blokade ini dilakukan warga lantaran aktifitas muatan batu bara kerap melintasi jalan raya yang berpotensi jalan raya rusak. Tampak jelas iring-iringan truk yang diduga memuat batu bara dari arah Kalimantan Selatan menabrak kursi plastik yang digunakan warga untuk memblokade jalan.</p>\n\n\n\n<p>Dilansir dari <a href="https://www.beritasatu.com/network/wartabanjar/76320/truk-batu-bara-diduga-asal-kalsel-terobos-blokade-warga-desa-batu-kajang">beritasatu.com</a>, Truk bermuatan besar itu diminta putar balik oleh masyarakat setempat karena dianggap meresahkan jalan umum. Selain menutupi jalan, warga memenuhi jalan dengan kendaraan bermotor dan membunyikan klakson.&nbsp;</p>\n\n\n\n<p>Hal ini dikarenakan warga tak ingin jalan umum berubah menjadi jalan rusak akibat pengangkutan material berat atau curah dengan dump truk di pertambangan.</p>\n\n\n\n<p><span style="background-color: #ff8c00;padding: 3px 8px;font-weight: bold;border-radius: 8px">Kesimpulan</span></p>\n\n\n\n<p>Unggahan “video truk nekat terobos dan tabrak tarub” merupakan konten yang menyesatkan (misleading content).</p>\n\n\n\n<p><strong><em>(Ditulis oleh Arief Putra Ramadhan)</em></strong></p>\n\n\n<div class="pagination clear mh-clearfix"> <span class="post-page-numbers current" aria-current="page"><span class="pagelink">1</span></span> <a href="https://turnbackhoax.id/2025/05/16/salah-video-truk-nekat-terobos-dan-tabrak-tarub-resepsi/2/" class="post-page-numbers"><span class="pagelink">2</span></a></div>	', '2025-05-17 00:16:36', '2025-05-17 00:16:36'),
	(4, '[SALAH] Video Prabowo dan Megawati di Sidang Paripurna Pemakzulan Gibran', 'salah-video-prabowo-dan-megawati-di-sidang-paripurna-pemakzulan-gibran', 'Aribowo Sasmito', 3, 'verified', 'nasional', 'https://turnbackhoax.id/2025/05/16/salah-video-prabowo-dan-megawati-di-sidang-paripurna-pemakzulan-gibran/', 'https://turnbackhoax.id/wp-content/uploads/2025/05/X-ps-msp-makzul-grr-HEADER-326x245.png', '<ul><li>Faktanya, video yang dibagikan adalah hasil manipulasi yang potongannya diambil dari rekaman kehadiran Prabowo dan Megawati di acara Upacara HUT ke-77 TNI pada Rabu, 5 Oktober 2022 lalu.</li><li>Unggahan yang membagikan video tersebut masuk ke kategori konten yang dimanipulasi (<em>manipulated content</em>).</li></ul><p>Pada Minggu (4/5/2025) beredar <a href="https://x.com/H4T14K4LN4L42/status/1919062084555555057"><span style="text-decoration: underline;">unggahan</span></a> di X (<a href="https://archive.ph/Of5Ht"><span style="text-decoration: underline;">arsip cadangan</span></a>) yang membagikan video dengan narasi:&nbsp;</p><blockquote>“Beneran nih @prabowo @gerindra @PDI_PerjuanganRakyat Indonesia menunggu kejelasannya…!Jangan hanya omon² seperti yg sudah².”</blockquote><p>Per arsip dibuat pada Minggu (5/5/2025) unggahan tersebut telah ditonton 4.679 ribu kali, mendapatkan jawaban 6 kali, dibagikan 13 kali, dan disukai 31 kali oleh pengguna X lainnya.</p><p><strong>Pemeriksaan Fakta</strong></p><p>Tim Pemeriksa Fakta MAFINDO (TurnBackHoax) menelusuri kebenaran klaim menggunakan perkakas <em>(tool)</em> InVID WeVerify yang memfragmentasi video ke dalam bentuk gambar/foto untuk mencari bingkai utama (<em>Keyframe</em>), hasilnya ditemukan foto yang dapat dijadikan petunjuk di bingkai utama #25.&nbsp;</p><p>Pencarian gambar (<em>image search</em>) di Keyframe #25 menggunakan Google Lens membawa ke sumber-sumber media nasional yang mempublikasikan foto yang dapat dijadikan petunjuk, salah satunya kanal YouTube KOMPASTV yang menggunakan foto tersebut untuk gambar pratinjau (thumbnail) di unggahan “Momen Megawati dan Prabowo Akrab Bercanda di Upacara HUT ke-77 TNI” yang tayang pada 5 Oktober tahun 2022 lalu.&nbsp;</p><p>Selain itu, pemeriksaan silang (<em>cross check</em>) menggunakan Google Videos dan Google News dengan kata kunci (<em>keyword</em>) “prabowo megawati hut tni au 77” menghasilkan berbagai video dan artikel berita dari sumber-sumber otoritatif yang mengkoroborasi mendukung unggahan di atas.&nbsp;</p><p>Berkaitan dengan sumber video yang disebarkan, berdasarkan tanda air (<em>watermark</em>) yang berada di video setelah dilakukan pencarian di TikTok ditemukan salah satu sumber unggahan dari akun @j3mbud_97 yang membagikan video dengan menambahkan narasi “#makzulkangibran” di unggahannya.</p><p><strong>Kesimpulan</strong></p><p>Unggahan tersebut masuk ke kategori konten yang dimanipulasi (<em>manipulated content</em>), faktanya video yang dibagikan adalah hasil manipulasi yang potongannya diambil dari rekaman kehadiran Prabowo dan Megawati di acara Upacara HUT ke-77 TNI pada Rabu, 5 Oktober 2022 lalu.</p>', '2025-05-17 00:16:37', '2025-05-18 20:40:56'),
	(5, '[SALAH] Israel Pakai Bom Buatan Turkiye untuk Menyerang Gaza', 'salah-israel-pakai-bom-buatan-turkiye-untuk-menyerang-gaza', 'Pemeriksa Fakta Junior', 10, 'verified', 'nasional', 'https://turnbackhoax.id/2025/05/16/salah-israel-pakai-bom-buatan-turkiye-untuk-menyerang-gaza/', 'https://turnbackhoax.id/wp-content/uploads/2025/05/header-turkiye-pasok-bom-untuk-israel-326x245.png', '<ul><li>Pusat Komunikasi dan Pemberantasan Disinformasi Turkiye telah membantah narasi mengenai bom buatan Turkiye yang dipakai Israel untuk menyerang Gaza.</li><li>Unggahan berisi klaim “Israel pakai bom buatan Turkiye untuk menyerang Gaza” merupakan konten palsu (fabricated content).</li></ul><p>Akun Facebook “Mas Dhar” pada Selasa (5/4/2025) membagikan foto <a href="https://www.facebook.com/photo/?fbid=9865041503519143&amp;set=a.1265141026842610"><span style="text-decoration: underline;">tangkapan layar</span></a> [<a href="https://archive.ph/3CPJT"><span style="text-decoration: underline;">arsip</span></a>] berisikan informasi berbahasa Arab dengan klaim bahwa Israel meluncurkan roket ke Gaza yang bertulisan “Buatan Turkiye – 2024”.</p><p>Berikut narasi dalam tangkapan layar tersebut (yang telah diterjemahkan ke Bahasa Indonesia):</p><blockquote>“Dalam adegan yang mengejutkan dan memilukan, pendudukan Zionis meluncurkan roket ke Gaza dengan tulisan “Made in Türkiye – 2024”, pada saat Türkiye dikenal karena sikap mendukungnya terhadap Gaza. Ironi yang menyakitkan adalah bahwa senjata dari negara yang menyatakan solidaritasnya digunakan saat ini untuk mengebom orang-orang yang tidak bersalah, menambah luka baru dalam ingatan pengepungan dan pengkhianatan.”“Türkiye memasok Israel dengan 5.000 jenis amunisi.”</blockquote><p>Pengunggah dalam takarir juga menambahkan narasi:</p><blockquote>“🇹🇷🇮🇱Benar2 membingungkan orang2 awam… Ankara (Turki) secara terang2an dan terbuka menyatakan dukungannya terhadap Gaza, akan tetapi tentara penjajah zionist menyerang wilayah Palestina dengan bom bertanda “Buatan Turki – 2024”.”</blockquote><p>Hingga Rabu (14/5/2025) unggahan tersebut telah disukai 37 pengguna, menuai 3 komentar, dan dibagikan ulang 13 kali.</p><p><strong>Pemeriksaan Fakta</strong></p><p>Disadur dari artikel Cek Fakta <a href="https://www.kompas.com/cekfakta/read/2025/05/06/153900382/-klarifikasi-pemerintah-turkiye-bantah-bomnya-dipakai-israel-di-gaza?page=all#page2"><span style="text-decoration: underline;">kompas.com</span></a>.</p><p>Pusat Komunikasi dan Pemberantasan Disinformasi Turkiye telah membantah narasi mengenai bom buatan Turkiye yang dipakai Israel untuk menyerang Gaza.</p><p>“Turkiye tidak memiliki perdagangan amunisi langsung atau tidak langsung dengan Israel di bidang industri pertahanan,” tulis badan tersebut melalui akun <a href="https://x.com/dmmiletisim/status/1758612287449960528"><span style="text-decoration: underline;">X</span></a> resminya “dmmiletisim” pada Februari 2024 lalu.</p><p>Industri pertahanan Turkiye PUN tidak memakai tanda “made by Turkey” untuk produk-produknya.</p><p><strong>Kesimpulan</strong></p><p>Unggahan berisi klaim “Israel pakai bom buatan Turkiye untuk menyerang Gaza” merupakan konten palsu (fabricated content).</p><p><strong><em>(Ditulis oleh Moch. Marcellodiansyah)</em></strong></p>', '2025-05-17 00:16:38', '2025-05-18 20:40:18'),
	(6, '[PENIPUAN] Tautan Lowongan Kerja PT Pupuk Indonesia', 'penipuan-tautan-lowongan-kerja-pt-pupuk-indonesia', 'Pemeriksa Fakta Junior', 7, 'verified', 'nasional', 'https://turnbackhoax.id/2025/05/16/penipuan-tautan-lowongan-kerja-pt-pupuk-indonesia/', 'https://turnbackhoax.id/wp-content/uploads/2025/05/header-pupuk-rekrutmen-bersama-326x245.png', '<ul><li>Proses Rekrutmen Bersama BUMN (termasuk Pupuk Indonesia) hanya dapat diakses melalui laman resmi Rekrutmen Bersama BUMN.</li><li>Unggahan berisi tautan “lowongan kerja PT Pupuk Indonesia” yang mengarah ke laman tak resmi merupakan konten tiruan (impostor content).</li></ul><p>Akun Facebook “Lokernas BUMN Swasta” pada Rabu (26/3/2025) membagikan <a href="https://www.facebook.com/photo?fbid=122119265570745010&amp;set=a.122103106436745010"><span style="text-decoration: underline;">tautan</span></a> [<a href="https://archive.ph/pMaK1"><span style="text-decoration: underline;">arsip</span></a>] disertai narasi:</p><blockquote>“Lowongan Kerja PT Pupuk Indonesia (Persero)<ul><li>PT Pupuk Kalimantan Timur</li><li>PT Petrokimia Gresik</li><li>PT Pupuk Sriwidjaja Palembang</li><li>PT Pupuk Iskandar Muda.</li></ul>(Silahkan pilih sesuai penempatan kerja yang anda inginkan)Ingin berkarier di BUMN dan berkonstribusi untuk Indonesia? Pupuk Indonesia Grup membuka kesempatan emas lewat Rekrutmen Bersama BUMN 2025!klik link untuk daftar:<figure data-trix-attachment="{&quot;contentType&quot;:&quot;image&quot;,&quot;height&quot;:16,&quot;url&quot;:&quot;https://lh7-rt.googleusercontent.com/docsz/AD_4nXfWh74g-x4YLbMZns4Pn9fG3EIwYGyiYIBvP9iVVREQCr30wMI2CSVcH8ue8lkTitjNPbo6o0U4yJAxxw4Emh4fhdJrvsLevTc_en6rin0QQiI_ORBjdQP-95IJrkNnjbZt5PVNsg?key=BbNFgBLSz_Qp27YvYjOByw&quot;,&quot;width&quot;:16}" data-trix-content-type="image" class="attachment attachment--preview"><img src="https://lh7-rt.googleusercontent.com/docsz/AD_4nXfWh74g-x4YLbMZns4Pn9fG3EIwYGyiYIBvP9iVVREQCr30wMI2CSVcH8ue8lkTitjNPbo6o0U4yJAxxw4Emh4fhdJrvsLevTc_en6rin0QQiI_ORBjdQP-95IJrkNnjbZt5PVNsg?key=BbNFgBLSz_Qp27YvYjOByw" width="16" height="16"><figcaption class="attachment__caption"></figcaption></figure><br> https://lowongankerja[dot]ydizy[dot]win/y4lp3wj/”</blockquote><p><strong>Pemeriksaan Fakta</strong></p><p>Tim Pemeriksa Fakta Mafindo (TurnBackHoax) menelusuri laman resmi Rekrutmen Bersama BUMN 2025 (<a href="http://rekrutmenbersama2025.fhcibumn.id"><span style="text-decoration: underline;">rekrutmenbersama2025.fhcibumn.id</span></a>) [<a href="https://archive.ph/TrZG8"><span style="text-decoration: underline;">arsip</span></a>]. Di bagian “Ketentuan Umum Pendaftaran” tertulis seluruh proses rekrutmen hanya dapat diakses melalui laman resmi tersebut.</p><p>TurnBackHoax kemudian mengakses tautan yang dibagikan akun Facebook “Lokernas BUMN Swasta”. Diketahui, tautan mengarah ke laman yang meminta data pribadi seperti:</p><ul><li>nama lengkap sesuai KTP,&nbsp;</li><li>usia,&nbsp;</li><li>jenis kelamin,&nbsp;</li><li>dan nomor telepon aktif Telegram.</li></ul><p><strong>Kesimpulan</strong></p><p>Unggahan berisi tautan “lowongan kerja PT Pupuk Indonesia” yang mengarah ke laman tak resmi merupakan konten tiruan (impostor content).</p><p><strong><em>(Ditulis oleh Moch. Marcellodiansyah)</em></strong></p>', '2025-05-17 00:16:39', '2025-05-18 20:39:46'),
	(7, '[BELUM TERBUKTI] Ekstrak Cabai dan Buah Nanas Bisa Hancurkan Parasit', 'belum-terbukti-ekstrak-cabai-dan-buah-nanas-bisa-hancurkan-parasit', 'Pemeriksa Fakta Junior', 1, 'verified', 'nasional', 'https://turnbackhoax.id/2025/05/16/belum-terbukti-ekstrak-cabai-dan-buah-nanas-bisa-hancurkan-parasit/', 'https://turnbackhoax.id/wp-content/uploads/2025/05/header-parasit-326x245.png', '\n\n\n<ul class="wp-block-list">\n<li>Perlu ada penelitian lebih lanjut untuk membuktikan apakah ekstrak beberapa bahan herbal—termasuk cabai dan nanas—bisa melawan parasit.</li>\n\n\n\n<li>Unggahan berisi klaim “ekstrak cabai dan buah nanas bisa hancurkan parasit manusia” merupakan konten yang menyesatkan (misleading content).</li>\n</ul>\n\n\n\n<hr class="wp-block-separator has-alpha-channel-opacity">\n\n\n\n<p>Akun Instagram “2winfarma” pada Minggu (23/3/2025) membagikan <a href="https://www.instagram.com/reel/DHhhYfrv5XE/">video</a> [<a href="https://archive.ph/BHF7X">arsip</a>], isinya diklaim memperlihatkan cairan mengandung parasit diletakkan di atas lempengan kaca dan diteteskan cairan ekstrak cabai.</p>\n\n\n\n<p>Unggahan disertai takarir:</p>\n\n\n\n<blockquote class="wp-block-quote is-layout-flow wp-block-quote-is-layout-flow">\n<p>“Yang bisa hanya BUAH NANAS menghancurkan parasit manusia ✅”</p>\n</blockquote>\n\n\n\n\n\n\n\n<p>Hingga Rabu (14/5/2025) unggahan tersebut telah disukai 24.000 pengguna dan menuai 844 komentar.</p>\n\n\n\n<p><span style="background-color: #ff8c00;padding: 3px 8px;font-weight: bold;border-radius: 8px">Pemeriksaan Fakta</span></p>\n\n\n\n<p>Disadur dari artikel Cek Fakta <a href="https://cekfakta.tempo.co/fakta/3575/belum-ada-bukti-video-manfaat-ekstrak-cabai-membunuh-parasit">tempo.co</a>.</p>\n\n\n\n<p>Tempo memverifikasi konten tersebut dengan menggunakan alat reverse image dan wawancara pakar kesehatan. Hasilnya, klaim tersebut membutuhkan penelitian lebih lanjut.&nbsp;</p>\n\n\n\n<p>Cairan merah yang digunakan dalam video, kemungkinan besar memang ekstrak cabai berlevel 3 juta SHU. Melalui pencarian dengan mesin pencari dan kata kunci, diketahui gambar botolnya dalam video yang beredar, sama dengan kemasan produk <a href="https://www.scovilla.com/en/Scovillas-Powerdrops-3Mio-Scoville-Units-3ml/100171">Scovillas Powerdrops</a> 3 juta SHU ukuran 3 mililiter.</p>\n\n\n\n<p>Dosen bidang Parasitologi Veteriner Fakultas Ilmu Kesehatan, Kedokteran, dan Ilmu Alam (FIKKIA,) Universitas Airlangga, drh. Aditya Yudhana,M.Si., mengatakan, perlu ada penelitian lebih lanjut untuk membuktikan apakah ekstrak beberapa bahan herbal—termasuk cabai dan nanas—bisa melawan parasit.</p>\n\n\n\n<p>Tanaman herbal memiliki banyak kandungan, sehingga membutuhkan identifikasi yang lebih detail. Seseorang juga tidak bisa langsung mengkonsumsi seluruh ekstrak herbal tersebut atau langsung memakan tanamannya, untuk mendapatkan manfaat tertentu.</p>\n\n\n\n<p>“Dalam proses pembuatan obat, prosesnya panjang. Uji klinis pada hewan, manusia, hingga mengevaluasi efek samping,” kata dia melalui WhatsApp, Selasa (6/5/2025).</p>\n\n\n\n<p>Menurut Aditya, tidak ada keterangan spesies cacing atau parasit yang digunakan dalam percobaan menggunakan mikroskop itu.Dia menduga jenis cacing tersebut termasuk dalam cacing gelang atau gilig (nematoda).</p>\n\n\n\n<p>“Kematian cacing-cacing tersebut belum tentu karena larutan cabai dan nanas, karena parameter yg digunakan tidak bisa divalidasi dengan jelas,” tandasnya.</p>\n\n\n\n<p><span style="background-color: #ff8c00;padding: 3px 8px;font-weight: bold;border-radius: 8px">Kesimpulan</span></p>\n\n\n\n<p>Unggahan berisi klaim “ekstrak cabai dan buah nanas bisa hancurkan parasit manusia” merupakan konten yang menyesatkan (misleading content).</p>\n\n\n\n<p><strong><em>(Ditulis oleh Moch. Marcellodiansyah)</em></strong></p>\n\n\n<div class="pagination clear mh-clearfix"> <span class="post-page-numbers current" aria-current="page"><span class="pagelink">1</span></span> <a href="https://turnbackhoax.id/2025/05/16/belum-terbukti-ekstrak-cabai-dan-buah-nanas-bisa-hancurkan-parasit/2/" class="post-page-numbers"><span class="pagelink">2</span></a></div>	', '2025-05-17 00:16:41', '2025-05-17 00:16:41'),
	(8, '[PENIPUAN] Program “Tunjangan Kesehatan dari Kemensos dan Kemenkes”', 'penipuan-program-tunjangan-kesehatan-dari-kemensos-dan-kemenkes', 'Bentang Febrylian', 2, 'verified', 'nasional', 'https://turnbackhoax.id/2025/05/14/penipuan-program-tunjangan-kesehatan-dari-kemensos-dan-kemenkes/', 'https://turnbackhoax.id/wp-content/uploads/2025/05/Screenshot-1957-326x245.png', '<ul><li>Video merupakan hasil rekayasa AI, kemungkinan atau probabilitasnya mencapai 70 persen. Konteks asli video adalah momen pembahasan usulan pembentukan peningkatan unit pelaksana Kementerian Sosial.</li><li>Unggahan video berisi klaim “Kemensos dan Kemenkes berikan tunjangan kesehatan” merupakan konten tiruan (impostor content).</li></ul><p>Akun Facebook “Humas Kemensos RI” pada Kamis (24/4/2025) membagikan <a href="https://www.facebook.com/61575789264241/videos/1170065747927786/"><span style="text-decoration: underline;">video</span></a> [<a href="https://archive.ph/DVOxF"><span style="text-decoration: underline;">arsip</span></a>], isinya memperlihatkan Sekretaris Jenderal Kementerian Sosial Robben Rico menuturkan narasi sebagai berikut:&nbsp;</p><blockquote>“Assalamualaikum Warrahmatullahi Wabarakatuh, saya Robin Rico Sekretaris Jenderal Kementerian Sosial ingin menyampaikan putusan raker kepada para tenaga kerja Indonesia bahwa putusan hasil rapat dengan Kementerian Kesehatan telah mengeluarkan anggaran tunjangan kesehatan kepada 20 orang setiap negara senilai Rp150.000.000. Untuk proses penerimaan bantuan tersebut, silakan inbox nama dan negara tempat anda bekerja”</blockquote><p>Hingga Rabu, (14/5/2025) unggahan sudah mendapat 180 tanda suka dan 91 komentar.</p><p><strong>Pemeriksaan Fakta</strong></p><p>Tim Pemeriksa Fakta Mafindo (TurnBackHoax) menggunakan Google Image Reverse untuk mencari tahu konteks asli video. Penelusuran teratas mengarah ke artikel di laman resmi <a href="https://kemensos.go.id/berita-foto/sekretariat-jenderal/rapat-usulan-pembentukan-peningkatan-unit-pelaksana-kemensos"><span style="text-decoration: underline;">kemensos.go.id</span></a> “Rapat Usulan Pembentukan Peningkatan Unit Pelaksana Kemensos” tayang Maret 2025.</p><p>Konteks asli video adalah momen ketika Sekretaris Jenderal Kementerian Sosial RI Robben Rico membahas usulan pembentukan peningkatan unit pelaksana Kementerian Sosial. Tidak ada pembicaraan tentang pemberian tunjangan kesehatan bersama Kementerian Kesehatan,</p><p>TurnBackHoax kemudian mengunduh video tersebut dan mengunggahnya ke Hive Moderation. Diketahui, video unggahan akun Facebook “Humas Kemensos RI” merupakan hasil rekayasa AI, kemungkinan atau probabilitasnya mencapai 70,8 persen.</p><p><strong>Kesimpulan</strong></p><p>Unggahan video berisi klaim “Kemensos dan Kemenkes berikan tunjangan kesehatan” merupakan konten tiruan (impostor content).</p>', '2025-05-17 00:16:42', '2025-05-18 20:38:07'),
	(9, '[SALAH] Roy Suryo Ditangkap karena Sebut Ijazah Jokowi Palsu', 'salah-roy-suryo-ditangkap-karena-sebut-ijazah-jokowi-palsu', 'Pemeriksa Fakta Junior', 3, 'verified', 'nasional', 'https://turnbackhoax.id/2025/05/14/salah-roy-suryo-ditangkap-karena-sebut-ijazah-jokowi-palsu/', 'https://turnbackhoax.id/wp-content/uploads/2025/05/Vania_Misleading-Content-HEADER-Dark-Background-326x245.png', '<ul><li>Konteks asli video adalah momen Polda Metro Jaya menahan dan menetapkan Roy Suryo sebagai tersangka dalam kasus dugaan ujaran kebencian bernuansa SARA. Kasus itu berkaitan dengan meme stupa Candi Borobudur yang disunting menyerupai wajah Jokowi.</li><li>Unggahan video berisi klaim “Roy Suryo ditangkap karena sebut ijazah Jokowi palsu” merupakan konten yang menyesatkan (misleading content).</li></ul><p>Akun TikTok “midonk reborn” pada Sabtu (21/3/2025) mengunggah <a href="https://vt.tiktok.com/ZSrGvLCNE/"><span style="text-decoration: underline;">video</span></a> [<a href="https://archive.ph/qA5Hq"><span style="text-decoration: underline;">arsip</span></a>] disertai narasi:</p><blockquote>“Roy Suryo di tahan polisi”</blockquote><p>Per Rabu (14/5/2025), unggahan tersebut telah dilihat lebih dari 1,2 juta kali, mendapat lebih dari 20 ribu tanda suka dan dibagikan ulang 1600-an kali.&nbsp;</p><p><strong>Pemeriksaan Fakta</strong></p><p>Tim Pemeriksa Fakta Mafindo (TurnBackHoax) memanfaatkan Google Lens untuk mencari tahu sumber video unggahan. Pencarian tangkapan layar untuk momen “siaran pers di Polda Metro Jaya” mengarah ke video serupa unggahan kanal YouTube KOMPASTV <a href="https://www.youtube.com/live/gzJLkdmbm00?si=ledEExZsUslLdr32"><span style="text-decoration: underline;">“BREAKING NEWS – Roy Suryo Ditahan Polisi Terkait Kasus Meme Stupa Borobudur</span></a>” yang tayang Agustus 2022. Potongan video diambil dari menit 6.25 sampai 6.48.</p><p>Tangkapan layar untuk momen “Roy Suryo turun dari tangga menggunakan penyangga leher” mengarah ke video di kanal YouTube Official iNews “<a href="https://youtu.be/SBSfO6CWI74?si=Me8lLzA7rfYYcfEU"><span style="text-decoration: underline;">PMJ Tahan Roy Suryo, Dijerat Pasal Penistaan Agama dan Terancam 6 Tahun Penjara</span></a>”, tayang Agustus 2022.</p><p>Konteks asli video adalah momen saat Polda Metro Jaya menahan dan menetapkan Roy Suryo sebagai tersangka dalam kasus dugaan ujaran kebencian bernuansa SARA. Kasus itu berkaitan dengan meme stupa Candi Borobudur yang disunting menyerupai wajah Joko Widodo, sama sekali tak ada kaitannya dengan ijazah palsu.</p><p><strong>Kesimpulan</strong></p><p>Unggahan video berisi klaim “Roy Suryo ditangkap karena sebut ijazah Jokowi palsu” merupakan konten yang menyesatkan (misleading content).</p><p><strong>(</strong><strong><em>Ditulis oleh Vania</em></strong><strong>)</strong></p>', '2025-05-17 00:16:43', '2025-05-18 20:37:15'),
	(10, '[PENIPUAN] Tautan Pendaftaran Beasiswa Pertamina', 'penipuan-tautan-pendaftaran-beasiswa-pertamina', 'Pemeriksa Fakta Junior', 9, 'verified', 'nasional', 'https://turnbackhoax.id/2025/05/14/penipuan-tautan-pendaftaran-beasiswa-pertamina/', 'https://turnbackhoax.id/wp-content/uploads/2025/05/Vania_Impostor-Konten-HEADER-Light-Background-326x245.png', '<ul><li>Pihak Pertamina telah menegaskan unggahan beasiswa bantuan pendidikan tersebut merupakan hoaks.</li><li>Unggahan berisi tautan “pendaftaran beasiswa Pertamina” yang mengarah ke laman tak resmi itu merupakan konten tiruan (impostor content).</li></ul><p>Akun Facebook “Program Beasiswa” pada Senin (28/4/2025) mengunggah <a href="https://www.facebook.com/permalink.php?story_fbid=pfbid0tSrGSzARvSZt3xrbP79wKUsAD5NpswPAkzTggTrRa52oQmJq38qwuKQivRafAyQtl&amp;id=61574117815589"><span style="text-decoration: underline;">tautan</span></a> [<a href="https://archive.ph/wip/1VriH"><span style="text-decoration: underline;">arsip</span></a>] beserta narasi:</p><blockquote>“‼️[Beasiswa Pertamina 2025 Resmi Dibuka!!!]‼️Berikut informasi persyaratan penting untuk persiapan kalian mendaftar Beasiswa Pertamina 2025. Info ini kami ambil berdasarkan info tahun sebelumnya!🎓✨Segera persiapkan dan pahami persyaratannya untuk meraih beasiswa!🤩Wujudkan mimpimu dengan beasiswa‼️💪🏻GRATIS TIDAK MEMUNGUT BIAYA&nbsp;Jangan lupa aktifkan notifikasi,like,save, dan follow kami&nbsp; agar tidak ketinggalaninfo beasiswa terbarunya!🔥📢Info daftar KLIK LINK DI BIO PROFIL”</blockquote><p>Unggahan serupa ditemukan di akun Facebook “<a href="https://www.facebook.com/permalink.php?story_fbid=pfbid0Bm9XdBFAUqAUivh3zcrHXQmx7k6VB6UGxgeEgxiGp6X69YEEqNoQpP1wc89DawKMl&amp;id=61574119259930"><span style="text-decoration: underline;">Ray Trianty Abbas</span></a>” [<a href="http://archive.ph/wip/VFtex"><span style="text-decoration: underline;">arsip</span></a>], “<a href="https://www.facebook.com/permalink.php?story_fbid=pfbid0BwQwcEBykTfB3YRUgvU2e4FVhaKDWifiNSDe4uFDFZcx4r4E4KCRribDzBi7mZnNl&amp;id=61575996300855"><span style="text-decoration: underline;">beasiswa</span></a>” [<a href="https://archive.ph/wip/cl3pD"><span style="text-decoration: underline;">arsip</span></a>], “<a href="https://www.facebook.com/permalink.php?story_fbid=pfbid02WWYtSDKfJmmoCAsQTBrZTDLxxkAUM5R249EUK49uenGxkXig9VvbzWwqEAhqWwPPl&amp;id=61569722231904"><span style="text-decoration: underline;">Barokah</span></a>” [<a href="https://archive.ph/fSqw3"><span style="text-decoration: underline;">arsip</span></a>].</p><p><strong>Pemeriksaan Fakta</strong></p><p>Disadur dari artikel Periksa Fakta <a href="https://tirto.id/hoaks-formulir-daftar-beasiswa-pertamina-2025-di-media-sosial-hbtU"><span style="text-decoration: underline;">tirto.id</span></a>.&nbsp;</p><p>Tirto mengakses tautan yang terdapat di bagian akhir sejumlah unggahan tersebut. Meski mengarah ke halaman yang berbeda, terdapat kesamaan dari laman yang dituju. Laman tersebut berbentuk formulir pendaftaran yang meminta data pribadi, seperti nama, jenis kelamin, dan nomor telepon. Tidak satupun yang mencantumkan lambang Pertamina, kebanyakan hanya bertuliskan halaman pendaftaran beasiswa.&nbsp;</p><p>Untuk memastikan hal itu, Tirto mencoba melakukan pemeriksaan menggunakan perangkat <a href="http://urlscan.io"><span style="text-decoration: underline;">URLScan.io.</span></a> Hasil pemindaian menunjukkan laman-laman berisi formulir tersebut kebanyakan mengarah ke laman “<a href="http://nofath.com"><span style="text-decoration: underline;">nofath.com</span></a>”, tidak ada hubungannya dengan Pertamina. Pertamina juga menyatakan kalau informasi tersebut adalah hoaks.</p><p>“Kami pastikan postingan beasiswa bantuan pendidikan tersebut merupakan hoaks dan cenderung penipuan,” ujar Vice President (VP) Corporate Communication Pertamina, Fadjar Djoko Santoso, kepada Tirto, Rabu (7/5/2025).</p><p>Dalam laman resmi Pertamina (<a href="http://www.pertamina.com"><span style="text-decoration: underline;">www.pertamina.com</span></a>), terdapat 2 program beasiswa saat ini, yaitu :&nbsp;</p><ul><li>Program <a href="https://beasiswa.pertaminafoundation.org/"><span style="text-decoration: underline;">Beasiswa</span></a> Pertamina Sobat Bumi 2025. Beasiswa itu menawarkan bantuan pendidikan, namun periode pendaftarannya antara 4 Februari 2025—4 Maret 2025 yang sudah lewat sekitar 2 bulan lalu.</li><li>Program <a href="https://beasiswa-cts.pertaminafoundation.org/"><span style="text-decoration: underline;">Beasiswa</span></a> Crewing Talent Scouting 2025. Program ini terkait langsung dengan anak usaha, Pertamina International Shipping (PIS). Beasiswa terbatas untuk program perwira laut dan diploma elektro. Prosesnya berjalan sampai 7 Mei 2025.</li></ul><p><strong>Kesimpulan</strong></p><p>Unggahan berisi tautan “pendaftaran beasiswa Pertamina” yang mengarah ke laman tak resmi itu merupakan konten tiruan (impostor content).</p><p><strong>(</strong><strong><em>Ditulis oleh Vania</em></strong><strong>)</strong></p>', '2025-05-17 00:16:44', '2025-05-18 20:36:44'),
	(11, '[SALAH] Puluhan Warga Bersholawat di Gunung Lapindo', 'salah-puluhan-warga-bersholawat-di-gunung-lapindo', 'Tim Kalimasada', 4, 'verified', 'nasional', 'https://turnbackhoax.id/2025/05/14/salah-puluhan-warga-bersholawat-di-gunung-lapindo/', 'https://turnbackhoax.id/wp-content/uploads/2025/05/HEADER-Dark-Background-27-326x245.png', '<ul><li>Tidak ditemukan informasi atau pemberitaan kredibel yang membenarkan klaim.</li><li>Unggahan berisi narasi “puluhan warga bersholawat di Gunung Lapindo” merupakan konten yang menyesatkan (misleading content).</li></ul><p>Akun Twitter (X) “fantsguy” pada Selasa (13/4/2025) mengunggah <a href="https://x.com/fantsguy/status/1911296659394609314?t=I0pW5XH0fu1O50cYWLi0Sg&amp;s=19"><span style="text-decoration: underline;">video</span></a> <a href="https://archive.ph/Pn4un"><span style="text-decoration: underline;">[arsip] </span></a>yang menampilkan kerumunan orang disertai narasi:</p><blockquote>Puluhan Warga Bersholawat di Gunung Lapindo</blockquote><p>Per Kamis (7/5/2025) video itu sudah dilihat lebih dari 500 ribu kali, disukai lebih dari 2 ribu kali, dibagikan ulang lebih dari 266 ribu kali dan menuai 755 komentar.</p><p><strong>Pemeriksaan Fakta</strong></p><p>Tim Pemeriksa Fakta Mafindo (TurnBackHoax) menelusuri kebenaran klaim dengan memasukkan kata kunci “puluhan warga bersholawat di Gunung Lapindo” ke mesin pencari Google. Tidak ditemukan informasi dari laman berita kredibel atau akun resmi pemerintahan yang membenarkan klaim tersebut.</p><p>TurnBackHoax kemudian menelusuri lebih lanjut dengan cara memasukkan&nbsp; potongan awal video lewat Google Lens. Ditemukan video serupa pada kanal Youtube milik <a href="https://www.youtube.com/watch?v=0TuDubd0Wj8"><span style="text-decoration: underline;">betv disway</span></a> dengan judul video “Viral, Warga Grobogan Gelar Sedekah Bumi di Bledug Kramesan” yang diunggah pada Jumat (18/4/2025). Fenomena alam berupa gunung lumpur atau mud volcano dan semburan lumpur di Grobogan, Jawa Tengah. Bisa terbentuk akibat Gempa yang memicu aktivitas mud volcano dengan membuka rekahan dan meningkatkan pergerakan material lumpur.&nbsp;</p><p><strong>Kesimpulan</strong></p><p>Unggahan berisi narasi “puluhan warga bersholawat di Gunung Lapindo” merupakan konten yang menyesatkan (misleading content).</p><p><strong><em>(Ditulis oleh Yudho Ardi)</em></strong></p>', '2025-05-17 00:16:45', '2025-05-18 20:36:00'),
	(12, '[SALAH] Salah Satu Misil Pakistan Menyerang Balik India', 'salah-salah-satu-misil-pakistan-menyerang-balik-india', 'Aribowo Sasmito', 10, 'verified', 'nasional', 'https://turnbackhoax.id/2025/05/14/salah-salah-satu-misil-pakistan-menyerang-balik-india/', 'https://turnbackhoax.id/wp-content/uploads/2025/05/beirut-X-pakistan-HEADER-326x245.png', '<ul><li>Faktanya, ledakan di video yang dibagikan adalah peristiwa meledaknya gudang yang berisi 2.750 ton Amonium Nitrat di Beirut, Lebanon pada tahun 2020 lalu.</li><li>Unggahan yang membagikan video tersebut masuk ke kategori konten yang menyesatkan (<em>misleading content</em>).</li></ul><p>Pada Rabu (7/5/2025) beredar <a href="https://x.com/faizalassegaf/status/1919880291373465688"><span style="text-decoration: underline;">unggahan</span></a> di X (<a href="https://archive.ph/vd7x3"><span style="text-decoration: underline;">arsip cadangan</span></a>) yang membagikan video dengan narasi:&nbsp;</p><blockquote>“✍️ BREAKING NEWS: Pakistan dan India terlibat perang terbuka dan saling menyerang secara brutal. (ket: Salah satu misil Pakistan menyerang balik India).Dunai semakin menuju konflik terbuka dan gejolak geopolitik yang mengkhawatirkan. Mengerikan!*FA*”</blockquote><p>Per tangkapan layar dibuat pada Kamis (8/5/2025) unggahan tersebut telah ditonton 99.7 ribu kali, mendapatkan jawaban 226 kali, dibagikan 307 kali, dan disukai 678 kali oleh pengguna X lainnya.</p><p><strong>Pemeriksaan Fakta</strong></p><p>Tim Pemeriksa Fakta MAFINDO (TurnBackHoax) menelusuri kebenaran klaim menggunakan perkakas <em>(tools)</em> InVID WeVerify yang memfragmentasi video untuk mencari bingkai utama (<em>keyframe</em>), hasilnya ditemukan sumber-sumber yang membagikan video yang salah satunya mengarahkan ke pengunggah pertama yaitu akun Youssef Kawtharani (@youssefkw) di Instagram yang membagikan videonya pada tahun 2020 lalu.&nbsp;</p><p>Selain itu, video yang sama pernah dipelintir sebelumnya pada tahun lalu (2024) di artikel “[SALAH] “Ledakan di Israel yang disembunyikan”” yang menghubungkan dengan situasi konflik di Israel.&nbsp;</p><p>Berkaitan dengan ketegangan/konflik Pakistan dengan India yang sedang berlangsung per artikel ini disusun, penelusuran menggunakan Google Videos dan Google News dengan kata kunci (<em>keyword</em>) “pakistan india tension” menghasilkan video dan berita dari sumber-sumber otoritatif yang mengabarkan dan memberikan pembaruan berkaitan dengan situasi tersebut.</p><p><strong>Kesimpulan</strong></p><p>Unggahan tersebut masuk ke kategori konten yang menyesatkan (<em>misleading content</em>), faktanya ledakan di video yang dibagikan adalah peristiwa meledaknya gudang yang berisi 2.750 ton Amonium Nitrat di Beirut, Lebanon pada tahun 2020 lalu.</p>', '2025-05-17 00:16:47', '2025-05-18 20:35:06'),
	(13, '[SALAH] Ahli Waris Bisa Disanksi kalau Orang Meninggal Tidak Lapor Pajak', 'salah-ahli-waris-bisa-disanksi-kalau-orang-meninggal-tidak-lapor-pajak', 'Pemeriksa Fakta Junior', 1, 'verified', 'nasional', 'https://turnbackhoax.id/2025/05/14/salah-ahli-waris-bisa-disanksi-kalau-orang-meninggal-tidak-lapor-pajak/', 'https://turnbackhoax.id/wp-content/uploads/2025/05/header-orang-meninggal-wajib-pajak-326x245.png', '<ul><li>Faktanya, ahli waris (dari wajib pajak yang sudah meninggal) hanya perlu mengajukan permohonan penghapusan NPWP.</li><li>Unggahan berisi narasi “ahli waris bisa disanksi kalau orang meninggal tidak lapor pajak” merupakan konten yang menyesatkan (misleading content).</li></ul><p>Akun Facebook “Jefri Papahnya Aqiela” pada Jumar (21/3/2025) membagikan <a href="https://www.facebook.com/photo/?fbid=507605232425564&amp;set=a.115795068273251"><span style="text-decoration: underline;">foto</span></a> [<a href="https://archive.ph/IjLpP"><span style="text-decoration: underline;">arsip</span></a>] berisi narasi:</p><blockquote>“Parah,Sekarang Orang Yang Sudah Mninggal Masih Wajib Lapor Pajak Jika Tidak,Ahli Waris Akan Kena Sangsi…!!!!”</blockquote><p>Hingga Rabu (14/5/2025) unggahan tersebut telah disukai oleh 100-an pengguna dan menuai 23 komentar.</p><p><strong>Pemeriksaan Fakta</strong></p><p>Disadur dari artikel Cek Fakta <a href="https://www.kompas.com/cekfakta/read/2025/05/06/084900682/-klarifikasi-orang-meninggal-tidak-ditagih-pajak-jika-ahli-waris-ajukan?page=all#page2"><span style="text-decoration: underline;">kompas.com</span></a>.</p><p>Wajib pajak yang sudah meninggal memang kadang dikirimi surat pemberitahuan dari kantor pajak, baik melalui surat fisik, maupun elektronik. Alasannya, NPWP mereka terdata masih aktif di DJP. Ketika warga yang memiliki Nomor Pokok Wajib Pajak (NPWP) meninggal dunia, data mereka tidak otomatis terhubung dengan kantor pajak.</p><p>Berdasarkan informasi di laman DJP, NPWP akan terus berstatus aktif apabila tidak mengajukan permohonan untuk menghapus kewajiban perpajakannya. Ahli waris sebagai perantara wajib pajak yang sudah meninggal wajib mengurus permohonan penghapusan NPWP ke kantor pajak. Hal ini sesuai dengan Peraturan Dirjen Pajak Nomor 04/PJ/2020.</p><p>“Wajib pajak yang NPWP-nya telah dihapus, maka tidak terdapat lagi kewajiban perpajakan yang harus dipenuhi,” kata Direktur Penyuluhan, Pelayanan, dan Hubungan Masyarakat DJP Kemenkeu, Dwi Astuti sebagaimana pernah ditulis <a href="https://www.kompas.com/tren/read/2025/01/24/120000665/npwp-disebut-akan-tetap-aktif-meski-pemiliknya-sudah-meninggal-ini"><span style="text-decoration: underline;">kompas.com</span></a>.</p><p>Permohonan dapat dilakukan secara langsung melalui Tempat Pelayanan Terpadu (TPT) di Kantor Pelayanan Pajak atau mengirimkan permohonan melalui pos ke alamat Kantor Pelayanan Pajak. Dokumen persyaratannya meliputi:</p><ul><li>akta kematian,&nbsp;</li><li>KTP,&nbsp;</li><li>KK,&nbsp;</li><li>surat pernyataan ahli waris, dan&nbsp;</li><li>surat keterangan terdaftar bagi wajib pajak orang.</li></ul><p><strong>Kesimpulan</strong></p><p>Unggahan berisi narasi “ahli waris bisa disanksi kalau orang meninggal tidak lapor pajak” merupakan konten yang menyesatkan (misleading content).</p><p><strong><em>(Ditulis oleh Moch. Marcellodiansyah)</em></strong></p>', '2025-05-17 00:16:48', '2025-05-18 20:34:25'),
	(14, '[SALAH] Video “Perdana Menteri Israel Ancam Presiden Prabowo”', 'salah-video-perdana-menteri-israel-ancam-presiden-prabowo', 'Pemeriksa Fakta Junior', 10, 'verified', 'nasional', 'https://turnbackhoax.id/2025/05/14/salah-video-perdana-menteri-israel-ancam-presiden-prabowo/', 'https://turnbackhoax.id/wp-content/uploads/2025/05/Header-Netanyahu-ancam-Prabowo-326x245.png', '<ul><li>Konteks asli video adalah momen ketika Netanyahu memberikan pesan menjelang Paskah. Tidak ada pernyataan atau ancaman yang ditujukan ke Prabowo.</li><li>Unggahan video berisi klaim “Perdana Menteri Israel ancam Presiden Prabowo” merupakan konten dengan konteks yang salah (false context).</li></ul><p>Akun Instagram “<a href="https://www.instagram.com/reel/DI5S5p5vsFI/"><span style="text-decoration: underline;">daniel_gerdy_ma</span></a>” [<a href="http://archive.ph/aGTeO"><span style="text-decoration: underline;">arsip</span></a>] pada Sabtu (26/4/2025) dan akun Facebook “<a href="https://www.facebook.com/61550935571002/posts/1347462372978013/?rdid=YHsyhvsNm8hLYJLx"><span style="text-decoration: underline;">MOBIL</span></a>” [<a href="https://archive.ph/xn2S1"><span style="text-decoration: underline;">arsip</span></a>] membagikan video yang menunjukkan Perdana Menteri Israel Benjamin Netanyahu memberikan ancaman kepada Presiden Indonesia Prabowo Subianto karena mendukung Palestina.&nbsp;</p><p>Berikut narasi terjemahan yang ditampilkan dalam video:</p><blockquote>“Tuan Presiden (Prabowo) situasi di wilayah konflik sebagai “ancaman besar” bagi siapa pun yang berani meninjaunya, termasuk Prabowo. Saya menyarankan untuk tidak terlalu dalam mendukung palestina sebab ini menyangkut keselamatan semua pihak.”</blockquote><p>Akun Instagram “<a href="https://www.instagram.com/reel/DI5S5p5vsFI/"><span style="text-decoration: underline;">daniel_gerdy_ma</span></a>” menambahkan narasi berikut dalam takarir:</p><blockquote>“✍🏾 PM Israel 🇮🇱 Benyamin Netanyahu peringatkan negara siapapun, termasuk Indonesia 🇮🇩: “Kepada Mr. Presiden Prabowo JANGAN TERLALU IKUT CAMPUR, PENTINGKAN KESELAMATAN ANDA, NEGARA ANDA, DARI PADA SIBUK BANTU TERORIS” Syaratnya ialah… TERORIS HAMAS BEBASKAN SANDERA.”</blockquote><p>Hingga Kamis (8/5/2025) unggahan Instagram&nbsp; “<a href="https://www.instagram.com/reel/DI5S5p5vsFI/"><span style="text-decoration: underline;">daniel_gerdy_ma</span></a>” telah disukai 54 pengguna dan menuai 21 komentar. Sementara unggahan Facebook “<a href="https://www.facebook.com/61550935571002/posts/1347462372978013/?rdid=YHsyhvsNm8hLYJLx"><span style="text-decoration: underline;">MOBIL</span></a>” mendapatkan 200-an tanda suka dan dikomentari 236 kali.</p><p><strong>Pemeriksaan Fakta</strong></p><p>Tim Pemeriksa Fakta Mafindo (TurnBackHoax) memasukkan tangkapan layar video ke Google Lens. <a href="https://turnbackhoax.id/wp-content/uploads/2025/05/Arsip-Google-Lens-Netanyahu-ancam-Prabowo.png"><span style="text-decoration: underline;">Hasil penelusuran</span></a> mengarah ke unggahan kanal YouTube <a href="https://www.youtube.com/watch?v=3svf7IeaDwU"><span style="text-decoration: underline;">Paisa Noticias</span></a> dengan judul yang sudah diterjemahkan “Benjamin Netanyahu dari Israel mengirimkan pesan solidaritas dan rasa terima kasih kepada warganya”, tayang April 2025.</p><p>Berdasarkan pengamatan TurnBackHoax, video yang dibagikan oleh Instagram “<a href="https://www.instagram.com/reel/DI5S5p5vsFI/"><span style="text-decoration: underline;">daniel_gerdy_ma</span></a>” dan Facebook “<a href="https://www.facebook.com/61550935571002/posts/1347462372978013/?rdid=YHsyhvsNm8hLYJLx"><span style="text-decoration: underline;">MOBIL</span></a>” diambil pada durasi 0:11 hingga 0:29. Untuk mengetahui konteks keseluruhan dari pernyataan Netanyahu yang berbahasa Ibrani tersebut, TurnBackHoax memanfaatkan alat transkrip dari <a href="https://anthiago.com/transcript/"><span style="text-decoration: underline;">anthiago.com</span></a> [<a href="https://turnbackhoax.id/wp-content/uploads/2025/05/Transkrip-pernyataan-Netanyahu.png"><span style="text-decoration: underline;">arsip</span></a>], kemudian menyalinnya ke <a href="https://chatgpt.com/share/681c831b-4e4c-8013-b8b3-c5d6190e1a8f"><span style="text-decoration: underline;">chatgpt.com</span></a> [<a href="https://archive.ph/aasSS"><span style="text-decoration: underline;">arsip</span></a>] untuk diterjemahkan ke dalam bahasa Indonesia.&nbsp;</p><p>Diketahui, konteks asli video adalah momen ketika Netanyahu memberikan pesan menjelang Paskah. Tidak ada pernyataan atau ancaman yang ditujukan ke Presiden Prabowo.</p><p><strong>Kesimpulan</strong></p><p>Unggahan video berisi klaim “Perdana Menteri Israel ancam Presiden Prabowo” merupakan konten dengan konteks yang salah (false context).</p><p><strong><em>(Ditulis oleh Moch. Marcellodiansyah)</em></strong></p>', '2025-05-17 00:16:49', '2025-05-18 20:33:29'),
	(15, '[PENIPUAN] Tautan “Pendaftaran BLT untuk Anak Sekolah”', 'penipuan-tautan-pendaftaran-blt-untuk-anak-sekolah', 'Pemeriksa Fakta Junior', 7, 'verified', 'nasional', 'https://turnbackhoax.id/2025/05/14/penipuan-tautan-pendaftaran-blt-untuk-anak-sekolah/', 'https://turnbackhoax.id/wp-content/uploads/2025/05/header-blt-anak-sekolah-326x245.png', '<ul><li>Informasi tentang bantuan langsung tunai (BLT) untuk anak sekolah dapat diakses di laman resmi <a href="http://pip.kemendikdasmen.go.id"><span style="text-decoration: underline;">pip.kemendikdasmen.go.id</span></a>.</li><li>Unggahan berisi tautan “pendaftaran BLT untuk anak sekolah” merupakan konten palsu (fabricated content).</li></ul><p>Akun Facebook “<a href="https://www.facebook.com/story.php?story_fbid=122093119928852707&amp;id=61575581210445&amp;rdid=murUcA6gkQV8nXBB"><span style="text-decoration: underline;">iin putri syahnas</span></a>” [<a href="https://archive.ph/cVvuG"><span style="text-decoration: underline;">arsip</span></a>] pada Selasa (15/4/2025) dan akun Facebook “<a href="https://www.facebook.com/story.php?story_fbid=122099706326851494&amp;id=61575544833638&amp;rdid=oqPZUuZxFhsIqpjM"><span style="text-decoration: underline;">sudarman</span></a>” [<a href="https://archive.ph/WRZyi"><span style="text-decoration: underline;">arsip</span></a>] pada Rabu (23/4/2025) membagikan tautan disertai narasi:</p><blockquote>“BLT Anak Sekolah Rp4.4Jt Cair Bulan Ini. Rp 900 ribu/bulan untuk siswa SD sederajat, Rp 1.2 Juta/bulan untuk siswa SMP sederajat, Rp 2 Juta/bulan untuk siswa SMA sederajat. Pemerintah kembali memberikan bantuan kepada anak sekolah untuk tingkat SD, SMP dan SMA Melalui Program Keluarga Harapan (PKH). Situs Resmi Klik Tombol Daftar di Bawah. daftarsekarang[dot]verifistatus[dot]web[dot]id”</blockquote><p>Hingga Rabu (14/5/2025) unggahan “iin putri syahnas” telah disukai 3.500 pengguna dan dibagikan ulang 89 kali.</p><p><strong>Pemeriksaan Fakta</strong></p><p>Tim Pemeriksa Fakta Mafindo (TurnBackHoax) menelusuri potret anak memegang Kartu Indonesia Pintar dan buku tabungan BRI dalam unggahan menggunakan Google Lens. <a href="https://turnbackhoax.id/wp-content/uploads/2025/05/Arsip-Google-Lens-penerima-BLT-anak-sekolah.png"><span style="text-decoration: underline;">Hasil penelusuran</span></a> mengarah ke artikel di laman resmi <a href="https://puslapdik.dikdasmen.go.id/batas-aktivasi-rekening-pip-diperpanjang-hingga-29-februari-2024/"><span style="text-decoration: underline;">puslapdik.dikdasmen.go.id</span></a> “Batas Aktivasi Rekening PIP Diperpanjang Hingga 29 Februari 2024”.</p><p>Dalam artikel yang terbit Februari 2024 itu dijelaskan bahwa Program Indonesia Pintar (PIP) merupakan bantuan pendidikan dari pemerintah—memiliki laman resmi <a href="http://pip.kemdikbud.go.id"><span style="text-decoration: underline;">pip.kemdikbud.go.id</span></a>—yang telah berpindah ke <a href="http://pip.kemendikdasmen.go.id"><span style="text-decoration: underline;">pip.kemendikdasmen.go.id</span></a>. Tidak disebutkan bahwa pendaftaran bantuan langsung tunai (BLT) untuk anak sekolah dilakukan melalui tautan seperti yang dibagikan oleh akun Facebook “<a href="https://www.facebook.com/story.php?story_fbid=122093119928852707&amp;id=61575581210445&amp;rdid=murUcA6gkQV8nXBB"><span style="text-decoration: underline;">iin putri syahnas</span></a>” dan “<a href="https://www.facebook.com/story.php?story_fbid=122099706326851494&amp;id=61575544833638&amp;rdid=oqPZUuZxFhsIqpjM"><span style="text-decoration: underline;">sudarman</span></a>”.</p><p>Sementara itu, berdasarkan <a href="https://kemensos.go.id/infografis/ditjen-perlindungan-dan-jaminan-sosial/bantuan-program-keluarga-harapan-pkh"><span style="text-decoration: underline;">laman resmi Kemensos</span></a> (<a href="https://kemensos.go.id/infografis/ditjen-perlindungan-dan-jaminan-sosial/bantuan-program-keluarga-harapan-pkh"><span style="text-decoration: underline;">kemensos.go.id</span></a>), Program Keluarga Harapan (PKH) untuk anak sekolah masuk dalam komponen pendidikan. PKH diberikan kepada Keluarga Penerima Manfaat (KPM) yang terdata dalam Data Terpadu Kesejahteraan Sosial (DTKS). Dilansir dari <a href="https://www.detik.com/sulsel/berita/d-7703547/cara-daftar-bansos-2025-online-lewat-hp"><span style="text-decoration: underline;">detik.com</span></a>, pendaftaran DTKS secara daring dilakukan melalui aplikasi “Cek Bansos”, tidak melalui tautan yang beredar di Facebook tersebut.</p><p>TurnBackHoax kemudian mengakses tautan yang dibagikan oleh kedua akun Facebook tersebut. Tautan hanya mengarah pada formulir yang meminta data pribadi, seperti daerah asal provinsi dan nomor Telegram aktif.</p><p><strong>Kesimpulan</strong></p><p>Unggahan berisi tautan “pendaftaran BLT untuk anak sekolah” merupakan konten palsu (fabricated content).</p><p><strong><em>(Ditulis oleh Moch. Marcellodiansyah)</em></strong></p>', '2025-05-17 00:16:50', '2025-05-18 20:32:54'),
	(16, '[PENIPUAN] Tautan “Pendaftaran Guru Sekolah Rakyat”', 'penipuan-tautan-pendaftaran-guru-sekolah-rakyat', 'Pemeriksa Fakta Junior', 7, 'verified', 'nasional', 'https://turnbackhoax.id/2025/05/14/penipuan-tautan-pendaftaran-guru-sekolah-rakyat/', 'https://turnbackhoax.id/wp-content/uploads/2025/05/header-rekrutmen-sekolah-rakyat-326x245.png', '<ul><li>Tautan yang beredar tidak mengarah ke laman resmi Kemensos maupun instansi pemerintah lainnya.</li><li>Unggahan berisi tautan “pendaftaran guru Sekolah Rakyat” merupakan konten palsu (fabricated content).</li></ul><p>Akun Facebook “yosi arsyani” pada Selasa (22/4/2025) membagikan <a href="https://www.facebook.com/story.php?story_fbid=122139639314792215&amp;id=61573766453026&amp;rdid=SVStBckaZF8Pjgux"><span style="text-decoration: underline;">tautan</span></a> [<a href="https://archive.ph/6C00d"><span style="text-decoration: underline;">arsip</span></a>] disertai narasi:</p><blockquote>“Pendaftaran Guru Sekolah Rakyat 2025 Resmi Dibuka! Pemerintah melalui Kementerian Sosial (Kemensos) dan Kementerian Pendidikan Dasar dan Menengah (Kemendikdasmen) meluncurkan Sekolah untuk Rakyat, sebuah program pendidikan khusus yang tidak hanya bertujuan memberikan akses belajar yang lebih luas tetapi juga mengajak masyarakat, khususnya para pendidik, untuk berperan aktif. proses rekrutmen untuk tenaga pengajar Guru Sekolah Rakyat resmi dibuka, memberikan kesempatan bagi para guru berdedikasi untuk mengabdikan diri dan membawa perubahan positif.”</blockquote><p>Hingga Rabu (14/5/2025) unggahan tersebut telah disukai oleh hampir 2.000 pengguna dan menuai 67 komentar.</p><p><strong>Pemeriksaan Fakta</strong></p><p>Disadur dari artikel Periksa Fakta <a href="https://tirto.id/hoaks-tautan-pendaftaran-guru-sekolah-rakyat-hbki"><span style="text-decoration: underline;">tirto.id</span></a>.</p><p>Tim Riset Tirto mengecek tautan dalam unggahan dengan menyalinnya ke laman <a href="https://urlscan.io/result/01969e39-14bf-76c3-9dca-821377d530f9/#summary"><span style="text-decoration: underline;">urlscan.io</span></a>. Tautan yang beredar tidak mengarah ke laman resmi Kemensos maupun instansi pemerintah lainnya. Laman pendaftaran itu justru meminta nomor Telegram pengguna. Saat mengecek akun media sosial resmi Kemensos, salah satunya Instagram, tidak ditemukan tautan pendaftaran guru Sekolah Rakyat seperti dalam klaim.</p><p>Poster dengan gambar laki-laki dan perempuan berseragam guru yang menyertai unggahan justru ditemukan diunggah oleh akun Instagram&nbsp; “<a href="https://www.instagram.com/p/DG0ErJex-EN/"><span style="text-decoration: underline;">nyalanesia</span></a>”. Poster itu tidak berkaitan dengan rekrutmen tenaga pendidik Sekolah Rakyat, melainkan rekrutmen penggerak literasi daerah.</p><p>Berdasarkan informasi dari laman <a href="https://kemensos.go.id/berita-terkini/menteri-sosial/Guru-dan-Murid-Sekolah-Rakyat-Diseleksi-Mulai-April-2025"><span style="text-decoration: underline;">resmi Kemensos</span></a>, proses seleksi peserta didik dan rekrutmen guru Sekolah Rakyat dijadwalkan dimulai April 2025. Salah satu tautan pendaftaran resmi tenaga pendidik di Sekolah Rakyat yakni <a href="https://bit.ly/GuruSekolahRakyat"><span style="text-decoration: underline;">https://bit.ly/GuruSekolahRakyat</span></a>. Laman itu digunakan untuk mendaftar sebagai guru di Sekolah Rakyat di Sulawesi Tenggara (Sultra).</p><p>Proses seleksi terbuka bagi guru ASN maupun non-ASN, dengan syarat melampirkan dokumen pendukung berupa:</p><ul><li>ijazah,&nbsp;</li><li>KTP,&nbsp;</li><li>SKCK, dan&nbsp;</li><li>surat pernyataan bersedia menjadi guru Sekolah Rakyat.</li></ul><p>Penerimaan tersebut diutamakan bagi lulusan Pendidikan Profesi Guru (PPG) Prajabatan yang belum berstatus ASN.</p><p><strong>Kesimpulan</strong></p><p>Unggahan berisi tautan “pendaftaran guru Sekolah Rakyat” merupakan konten palsu (fabricated content).</p><p><strong><em>(Ditulis oleh Moch. Marcellodiansyah)</em></strong></p>', '2025-05-17 00:16:51', '2025-05-18 20:32:14'),
	(17, '[PENIPUAN] Tautan “Pendaftaran Bantuan Benih untuk Budidaya Ikan Air Tawar”', 'penipuan-tautan-pendaftaran-bantuan-benih-untuk-budidaya-ikan-air-tawar', 'Pemeriksa Fakta Junior', 7, 'verified', 'nasional', 'https://turnbackhoax.id/2025/05/14/penipuan-tautan-pendaftaran-bantuan-benih-untuk-budidaya-ikan-air-tawar/', 'https://turnbackhoax.id/wp-content/uploads/2025/05/header-budidaya-ikan-326x245.png', '<ul><li>Faktanya, pendaftaran bantuan tidak dilakukan lewat tautan, tetapi dengan mengajukan proposal permohonan bantuan ke kepala dinas terkait di tingkat kabupaten/kota.</li><li>Unggahan berisi tautan “pendaftaran bantuan benih untuk budidaya ikan air tawar” merupakan konten tiruan (impostor content).</li></ul><p>Akun Facebook “Program Pemerintah Terbaru” dengan foto profil logo Kementerian Kelautan dan Perikanan pada Sabtu (19/4/2025) membagikan <a href="https://www.facebook.com/photo?fbid=122096026232852527&amp;set=a.122095741682852527"><span style="text-decoration: underline;">foto</span></a> [<a href="https://archive.ph/4oMpS"><span style="text-decoration: underline;">arsip</span></a>] berisi informasi:</p><blockquote>“PROGRAM BANTUAN PEMERINTAH TAHUN ANGGARAN 2025. BANTUAN BUDIDAYA IKAN AIR TAWAR:&nbsp;<ul><li>BENIH IKAN AIR TAWAR (Ikan Nila,Lele,Gurami,Emas dan Bandeng)&nbsp;</li><li>KOLAM BIOFLOK,&nbsp;</li><li>POMPA AIR”</li></ul></blockquote><p>Pada takarir, pengunggah juga menambahkan narasi:</p><blockquote>“Program Pemerintah Tahun Anggaran 2025 Menyalurkan bantuan Benih ikan air tawar. Kriteria Persyaratan Calon Penerima Bantuan Pemerintah tahun Anggaran 2025 :&nbsp;<ul><li>Warga Negara Indonesia&nbsp;</li><li>Memiliki Lahan untuk dikelolah&nbsp;</li><li>Perorangan &amp; kelompok&nbsp;</li><li>Bertanggung jawab bantuan Pemerintah Bersifat Gratis, tidak ada biaya pendaftaran.”</li></ul></blockquote><p>Hingga Rabu (14/5/2025) unggahan tersebut telah disukai oleh 4 pengguna dan menuai 7 komentar.</p><p><strong>Pemeriksaan Fakta</strong></p><p>Tim Pemeriksa Fakta Mafindo (TurnBackHoax) memasukkan kata kunci “bagaimana cara mendapatkan bantuan benih ikan air tawar dari pemerintah?” ke kolom pencarian Google. <a href="https://turnbackhoax.id/wp-content/uploads/2025/05/Hasil-pencarian-cara-mendapatkan-bantuan-budidaya-ikan-dari-pemerintah.png"><span style="text-decoration: underline;">Hasil pencarian</span></a> mengarah ke dokumen petunjuk teknis bantuan benih ikan yang terpublikasi di laman resmi Kementerian Kelautan dan Perikanan, <a href="https://ppid.kkp.go.id/media/uploads/document_regulation/Kep_Dirjen_PB_No_381_Juknis_Bantuan_Benih_TA_2024.pdf"><span style="text-decoration: underline;">kkp.go.id</span></a>.</p><p>Dari dokumen tersebut diketahui alur mendapatkan bantuan benih ikan sebagai berikut:</p><ol><li>Kelompok pembudidaya ikan (pokdakan) atau calon penerima bantuan mengajukan proposal permohonan bantuan benih ikan kepada kepala dinas yang membidangi perikanan di tingkat kabupaten/kota,</li><li>Dinas Kabupaten/Kota akan melakukan verifikasi dan evaluasi terhadap kelayakan calon penerima. Jika memenuhi syarat, Dinas akan memberikan rekomendasi dan meneruskan proposal ke Dinas Provinsi atau langsung ke Unit Pelaksana Teknis (UPT) Direktorat Jenderal Perikanan Budidaya (DJPB).</li><li>UPT DJPB memverifikasi dan menetapkan penerima,&nbsp;</li><li>Benih disalurkan ke kelompok penerima.</li></ol><p>Dari pengamatan TurnBackHoax, akun Facebook “Program Pemerintah Terbaru” mencantumkan tautan pendaftaran di bagian profil. Tautan tersebut tidak mengarah ke laman resmi Kementerian Kelautan dan Perikanan, melainkan ke sebuah formulir yang meminta informasi jenis ikan dan lokasi lahan, lalu mengarahkan pengguna untuk masuk ke akun Telegram saat menekan tombol “daftar sekarang.”</p><p>Sementara itu, dokumen resmi dari Kementerian Kelautan dan Perikanan yang tersedia di laman resminya tidak memuat instruksi untuk mengisi formulir melalui tautan semacam itu.</p><p><strong>Kesimpulan</strong></p><p>Unggahan berisi tautan “pendaftaran bantuan benih untuk budidaya ikan air tawar” merupakan konten tiruan (impostor content).</p><p><strong><em>(Ditulis oleh Moch. Marcellodiansyah)</em></strong></p>', '2025-05-17 00:16:53', '2025-05-18 20:31:21'),
	(18, '[SALAH] Dokumentasi “Koalisi Militer Indonesia-Rusia di Gaza”', 'salah-dokumentasi-koalisi-militer-indonesia-rusia-di-gaza', 'Pemeriksa Fakta Junior', 10, 'verified', 'nasional', 'https://turnbackhoax.id/2025/05/14/salah-dokumentasi-koalisi-militer-indonesia-rusia-di-gaza/', 'https://turnbackhoax.id/wp-content/uploads/2025/05/header-koalisi-rusia-indonesia-di-gaza-326x245.png', '<ul><li>Dokumentasi dalam unggahan yang beredar berasal dari peristiwa yang berbeda, tidak ada hubungannya dengan operasi gabungan Indonesia-Rusia di Gaza.</li><li>Unggahan berisi klaim “koalisi militer Indonesia-Rusia di Gaza” merupakan konten palsu (fabricated content).</li></ul><p>Akun TikTok “teenanancell” pada Jumat (25/4/2025) membagikan <a href="https://www.tiktok.com/@teenanancell/video/7496322129265200439"><span style="text-decoration: underline;">video</span></a> [<a href="https://archive.ph/PNcKg"><span style="text-decoration: underline;">arsip</span></a>] berisi narasi:</p><blockquote>“Koalisi Indonesia Rusia lawan Israel”<br>“Operasi dimulai pada pukul 02.00 dini hari 14 April 2025 dalam gelap malam dan badai pasir yang menutup langit sinai, pasukan udara Rusia melumpuhkan sistem pertahanan Israel di selatan drone siluman uraga milik Rusia, menghancurkan radar dan pangkalan militer dengan presisi brutal. Bersamaan dengan itu 6.000 pasukan elit Indonesia dari Kopassus marinir dan penjaga disusupkan dari laut melalui terowongan bawah tanah yang telah disiapkan oleh jaringan logistik hamas yang kini bersekutu diam-diam dengan Jakarta dalam waktu 72 jam jalur Gaza yang selama ini menjadi wilayah terisolasi dan dijaga ketat IDF jatuh ke tangan koalisi Indonesia Rusia militer Israel terpukul logistik terganggu dan moral pasukan merosot drastis bendera Indonesia dan Rusia berkibar di atas reruntuhan markas shimpetika unit di tengah kehancuran yang tak berkesudahan datang 2 kekuatan dari timur Indonesia dan Rusia yang membentuk aliansi militer paling mengejutkan abad ini dari pangkalan udara. Fladiostok, hingga pelabuhan Surabaya persiapan berlangsung diam-diam namun sistematis apa yang awalnya terlihat sebagai latihan militer gabungan ternyata hanyalah kedok untuk sebuah operasi besar yang akan mengubah wajah dunia koalisi Indonesia tidak lahir dari kedekatan budaya atau sejarah.”</blockquote><p>Hingga Rabu (14/5/2025) unggahan tersebut telah disukai oleh 7.000-an pengguna dan menuai 600-an komentar.</p><p><strong>Pemeriksaan Fakta</strong></p><p>Disadur dari artikel Cek Fakta <a href="https://www.tempo.co/cekfakta/keliru-video-koalisi-indonesia-rusia-melawan-israel-1303877"><span style="text-decoration: underline;">tempo.co</span></a>.</p><p>Tempo memverifikasi video itu dengan bantuan Google Lens, mesin penelusuran Google dan YouTube. Hasilnya, video tersebut adalah gabungan beberapa foto dan video pendek dari peristiwa berbeda.&nbsp;</p><p>Foto pertama pada bagian atas video serupa dengan cuplikan dari latihan militer skala besar Vostok 2018 yang diunggah oleh kanal YouTube <a href="https://www.youtube.com/watch?v=b8ec7Wohdt0"><span style="text-decoration: underline;">The Sun</span></a> pada Jumat (13/9/2018). Latihan ini berlangsung di Siberia timur dan melibatkan sekitar 300.000 tentara Rusia serta partisipasi dari militer China dan Mongolia.</p><p>Foto kedua pada bagian bawah video yang memperlihatkan barisan panjang pasukan dan kendaraan tempur, juga merupakan bagian dari parade militer Vostok 2018. Cuplikan ini sebelumnya diunggah oleh kanal YouTube <a href="https://www.youtube.com/watch?v=WSl68xXf85E&amp;t"><span style="text-decoration: underline;">Russian Military Capability</span></a> pada Kamis (14/10/2025).</p><p>Foto ketiga yang menampilkan kendaraan militer berwarna putih bertuliskan “UN” serupa dengan unggahan kanal YouTube <a href="https://www.youtube.com/shorts/Xh8PANiJ9gE"><span style="text-decoration: underline;">Andrian Lingga</span></a> yang menunjukkan partisipasi TNI sebagai bagian dari misi perdamaian Perserikatan Bangsa-Bangsa. Video tersebut tidak menjelaskan lokasi tugas pasukan, namun diketahui bahwa Indonesia pernah mengirim pasukan perdamaian ke berbagai wilayah seperti Lebanon, Kongo (2020), Mali (2015), Sudan (2013) dan Kamboja.</p><p>Indonesia dan Rusia tidak menjalin kerja sama militer untuk beroperasi di Gaza. Dilansir dari <a href="https://en.antaranews.com/news/346237/indonesia-seeks-to-bolster-defense-cooperation-with-russia"><span style="text-decoration: underline;">antaranews.com</span></a>, Menteri Pertahanan Sjafrie Sjamsoeddin dan Sekretaris Dewan Keamanan Rusia, Sergei K. Shoigu, membahas potensi kerja dalam pertemuan bilateral di Jakarta pada 25 Februari 2025 lalu. Kerja sama yang mereka jajaki antara lain berupa pelatihan bersama, transfer teknologi, dan pertukaran prajurit.</p><p>Sedangkan terkait Gaza, Presiden Prabowo Subianto pada 9 April 2025 mengatakan, Indonesia telah mengirimkan bantuan medis dan menerjunkan tenaga medis ke wilayah konflik tersebut sebagai bentuk komitmen terhadap aksi kemanusiaan di Gaza.</p><p>Presiden Prabowo juga menyampaikan kesediaan Indonesia untuk menampung sementara para korban, anak yatim piatu, dan warga negara yang terdampak konflik di Gaza. Ia telah memerintahkan Menteri Luar Negeri untuk berkomunikasi dengan pihak-pihak terkait di Palestina untuk membahas mekanisme evakuasi korban dan relokasi ke Indonesia.</p><p><strong>Kesimpulan</strong></p><p>Unggahan berisi klaim “koalisi militer Indonesia-Rusia di Gaza” merupakan konten palsu (fabricated content).</p><p><strong><em>(Ditulis oleh Moch. Marcellodiansyah)</em></strong></p>', '2025-05-17 00:16:54', '2025-05-18 20:30:29'),
	(19, '[PENIPUAN] Tautan “Lowongan Kerja Indonesia Morowali Industrial Park (IMIP)”', 'penipuan-tautan-lowongan-kerja-indonesia-morowali-industrial-park-imip', 'Pemeriksa Fakta Junior', 7, 'verified', 'nasional', 'https://turnbackhoax.id/2025/05/13/penipuan-tautan-lowongan-kerja-indonesia-morowali-industrial-park-imip/', 'https://turnbackhoax.id/wp-content/uploads/2025/05/HEADER-Dark-Background-11-326x245.png', '<ul><li>Informasi resmi tentang lowongan kerja PT IMIP Indonesia hanya diumumkan di laman <a href="https://imip.co.id./"><span style="text-decoration: underline;">imip.co.id</span></a> dan media-media sosial resmi perusahaan.</li><li>Unggahan berisi tautan “lowongan pekerjaan PT IMIP Indonesia”&nbsp; merupakan konten palsu (fabricated content).</li></ul><p>Akun TikTok “lowongan.kerja.20342” pada Selasa (29/4/2025) mengunggah <a href="https://www.tiktok.com/@lowongan.kerja.20342/video/7498495328249728261"><span style="text-decoration: underline;">video</span></a> [<a href="https://archive.ph/AVU3q"><span style="text-decoration: underline;">arsip</span></a>] berisi informasi lowongan pekerjaan PT Indonesia Morowali Industrial Park (IMIP).&nbsp;</p><p>Berikut narasi dalam unggahan:</p><blockquote>“Lowongan Kerja Terbaru 2025<br>PT. IMIP INDONESIA<br>RP 6.000.000 – RP 12.000.000<br>PENDAFTARAN TERBUKA UNTUK UMUMPRIA/WANITA<br>SMK/SMA SEMUA JURUSAN<br>UMUR 18-55 TAHUN<br>FOTO KTP<br>POSISI BISA DIPILIH<br>IJAZAH/NON IJAZAH<br>PENGALAMAN/NON PENGALAMAN TERSEDIA TRAINING<br>9 JAM BEKERJA PERGANTIAN SHIFT”.</blockquote><p>Dalam kolom komentar, akun tersebut mengimbau warganet yang tertarik untuk mendaftar lewat tautan yang tersemat di profil akun.</p><p>Hingga Selasa (13/5/2025) unggahan telah disukai 8 pengguna dan dibagikan ulang dua kali.&nbsp;</p><p><strong>Pemeriksaan Fakta</strong></p><p>Tim Pemeriksa Fakta Mafindo (TurnBackHoax) mengakses <a href="https://imip.co.id./"><span style="text-decoration: underline;">laman resmi</span></a> IMIP, <a href="https://imip.co.id./"><span style="text-decoration: underline;">imip.co.id</span></a>. Hasilnya, ditemukan <a href="https://imip.co.id/masyarakat-harus-waspada-atas-penipuan-info-loker-pt-imip/"><span style="text-decoration: underline;">artikel</span></a> “Masyarakat Harus Waspada Atas Penipuan Info Loker PT IMIP” yang dipublikasikan Jumat (2/5/2025). Artikel itu menuliskan kalau banyak hoaks lowongan pekerjaan yang mencatut PT IMIP dengan persyaratan yang terlalu sederhana, yaitu hanya memerlukan KTP tanpa ijazah dan syarat lainnya.</p><p>Head of Media Relations PT IMIP telah menyatakan pengumuman-pengumuman tersebut adalah hoaks, dan lowongan pekerjaan resmi dari PT IMIP hanya diinformasikan melalui:</p><ul><li><a href="https://imip.co.id/"><span style="text-decoration: underline;">imip.co.id</span></a></li><li><a href="https://instagram.com/officialIMIP"><span style="text-decoration: underline;">Instagram “officialIMIP</span></a>”</li><li><a href="https://www.tiktok.com/@imipofficial"><span style="text-decoration: underline;">TikTok “imipofficial</span></a>”</li><li><a href="https://facebook.com/OfficialIMIP"><span style="text-decoration: underline;">Facebook “OfficialIMIP</span></a>”</li><li><a href="https://youtube.com/OfficialIMIP-New"><span style="text-decoration: underline;">YouTube “OfficialIMIP-New</span></a>”</li></ul><p>TurnBackHoax kemudian mengakses tautan yang tersemat di bio akun pengunggah. Diketahui, tautan mengarah ke formulir yang meminta pengisian nama lengkap sesuai KTP dan nomor ponsel Telegram aktif. Ketika diteruskan, pelamar diminta untuk memasukkan kode verifikasi untuk masuk ke akun Telegram.&nbsp;</p><p><strong>Kesimpulan</strong></p><p>Unggahan berisi tautan “lowongan pekerjaan PT IMIP Indonesia”&nbsp; merupakan konten palsu (fabricated content).</p><p><strong>(</strong><strong><em>Ditulis oleh Zahra</em></strong><strong>)</strong></p>', '2025-05-17 00:16:55', '2025-05-18 20:29:43'),
	(20, '[SALAH] 41 Pasukan Khusus TNI Gugur Saat Melakukan Misi Kemanusiaan di Gaza', 'salah-41-pasukan-khusus-tni-gugur-saat-melakukan-misi-kemanusiaan-di-gaza', 'Tim Kalimasada', 5, 'verified', 'nasional', 'https://turnbackhoax.id/2025/05/09/salah-41-pasukan-khusus-tni-gugur-saat-melakukan-misi-kemanusiaan-di-gaza/', 'https://turnbackhoax.id/wp-content/uploads/2025/05/HEADER-Dark-Background-3-326x245.png', '<ul><li>Kapuspen TNI Brigjen TNI, Kristomei Sianturi menyatakan bahwa pernyataan yang beredar merupakan hoaks.&nbsp;</li><li>Unggahan dengan narasi “41 pasukan khusus TNI gugur saat melakukan misi kemanusiaan di Gaza” merupakan konten palsu (fabricated content).</li></ul><p>Pada Selasa (29/4/2025) beredar pesan berantai di WhatsApp <a href="https://archive.ph/wip/qgmm0"><span style="text-decoration: underline;">[arsip]</span></a> dengan narasi seperti berikut :</p><blockquote>INNALILLAAHI WAINNA ILAIHI RAAJI’UUN..&nbsp;LETKOL inf. WISNU gugur beserta 40 Anggota Pasukan Khusus TNI yang bersandi GARUDA HITAM PBB dalam Misinya di Gaza akibat dibombardir pesawat gabungan Israel dan AS pada Jum’at MaLam 25 April 2025 Setelah sebelumnya Menghancurkan Gudang senjata milik Israel di Otoritas GAZA..&nbsp;TNI HEBAAAT DI GAZA, SEMOGA ALLAAH Subhaanahuh Wata’ala TETAP MELINDUNGI TNI DAN MEMBERI KEMENANGAN TNI.. MEREKA GUGUR SEBAGAI SYUHADA KARENA MEMBELA MEREKA YANG DITINDAS OLEH ISRAEL YANG DIDUKUNG PENUH OLEH AS</blockquote><p><strong>Pemeriksaan Fakta</strong></p><p>Disadur dari pemberitaan <a href="https://www.antaranews.com/berita/4802945/hoaks-41-pasukan-khusus-tni-gugur-saat-melakukan-misi-kemanusiaan-di-gaza"><span style="text-decoration: underline;">antarnews.com</span></a></p><p>Kapuspen TNI Brigjen TNI Kristomei Sianturi kepada ANTARA menyatakan bahwa pernyataan yang beredar merupakan hoaks.</p><p>“Ini hoaks,” kata Sianturi kepada Antara, Selasa (29/4/2025).</p><p>Ia menjelaskan, Indonesia terus mendukung perjuangan rakyat dan pemerintah Palestina untuk meraih kemerdekaan. Dukungan ini diberikan secara konsisten, baik di dalam negeri maupun di dunia internasional.</p><p><strong>Kesimpulan</strong></p><p>Unggahan dengan narasi “41 pasukan khusus TNI gugur saat melakukan misi kemanusiaan di Gaza” merupakan konten palsu (fabricated content).</p>', '2025-05-17 00:16:56', '2025-05-18 20:28:40'),
	(21, 'Tautan loker bodong', 'tautan-loker-bodong', 'Admin', 7, 'verified', 'lokal', 'https://www.facebook.com/', 'https://th.bing.com/th/id/OIP.IB6r5J422dRkua0azPALYwHaEK?rs=1&pid=ImgDetMain', '<p>Hati-hati ada loker bodong di facebook</p>', '2025-05-19 19:40:55', '2025-05-19 19:40:55'),
	(22, '[PENIPUAN] Tautan “Pendaftaran Giveaway PLN”', 'penipuan-tautan-pendaftaran-giveaway-pln', 'Pemeriksa Fakta Junior', 7, 'verified', 'nasional', 'https://turnbackhoax.id/2025/06/04/penipuan-tautan-pendaftaran-giveaway-pln/', 'https://turnbackhoax.id/wp-content/uploads/2025/06/HEADER-Dark-Background-326x245.png', '<ul><li>Faktanya, PLN tidak pernah menyelenggarakan program giveaway.</li><li>Unggahan berisi tautan “pendaftaran giveaway PLN” merupakan konten tiruan (impostor content).</li></ul><p>Pada Kamis (29/5/2025) akun Facebook “info terkini” membagikan <a href="https://www.facebook.com/permalink.php?story_fbid=122102316680889118&amp;id=61576673540092"><span style="text-decoration: underline;">tautan</span></a> [<a href="https://archive.ph/wip/fXAj0"><span style="text-decoration: underline;">arsip</span></a>] disertai narasi :</p><blockquote>“GIVEAWAY PLN INDONESIA POWER 2025Mau hadiah jutaan rupiah yukkkkk ikutan soalnya bakal ada 300 orang pemenang lohHadiah1 uang tunai ratusan juta&nbsp;2 Gratis token listrik 1 tahunHadiah gratis tampa dipungut biaya apapunAyo daftarkan diri anda sekarang jugaKlik link di bawah”</blockquote><p>Hingga Rabu (4/6/2025), unggahan telah mendapatkan 52 tanda suka dan 9 komentar.</p><p><strong>Pemeriksaan Fakta</strong></p><p>Disadur dari artikel Cek Fakta <a href="https://www.kompas.com/cekfakta/read/2025/05/30/185800382/-hoaks-tautan-untuk-dapat-giveaway-pln-berhadiah-uang-tunai"><span style="text-decoration: underline;">kompas.com</span></a></p><p>Tim Cek Fakta Kompas.com menghubungi PLN untuk mengonfirmasi kebenaran tautan pendaftaran giveaway tersebut.</p><p>Manager Komunikasi dan TJSL PLN UID Jateng-DIY, Prayudha Fasya Perdana mengatakan, giveaway mengatasnamakan PLN yang beredar di Facebook tersebut adalah hoaks.</p><p>“PLN tidak pernah menyelenggarakan program giveaway seperti yang dimaksud. Apalagi yang meminta data pribadi, OTP, atau pungutan biaya,” kata Yudha kepada Kompas.com, Jumat (30/5/2025).</p><p>Yudha mengimbau masyarakat untuk selalu waspada terhadap modus penipuan yang mengatasnamakan PLN.</p><p>Informasi resmi terkait PLN dapat diperoleh melalui kanal resmi seperti Contact Center PLN 123, aplikasi PLN Mobile, situs web www.pln.co.id, serta laman media sosial PLN yang sudah terverifikasi (centang biru).</p><p><strong>Kesimpulan</strong></p><p>Unggahan berisi tautan “pendaftaran giveaway PLN” merupakan konten tiruan (impostor content).</p><p><strong>(</strong><strong><em>Ditulis oleh Raymondha Elsha</em></strong><strong>)</strong></p>', '2025-06-03 20:57:52', '2025-07-27 21:21:20'),
	(23, '[PENIPUAN] Tautan Rekrutmen Relawan Baznaz untuk Iduladha', 'penipuan-tautan-rekrutmen-relawan-baznaz-untuk-iduladha', 'Pemeriksa Fakta Junior', 7, 'verified', 'nasional', 'https://turnbackhoax.id/2025/06/03/penipuan-tautan-rekrutmen-relawan-baznaz-untuk-iduladha/', 'https://turnbackhoax.id/wp-content/themes/mh-magazine-lite/images/placeholder-medium.png', '<ul><li>Baznas telah menegaskan kabar rekrutmen yang beredar adalah informasi palsu.</li><li>Unggahan berisi tautan “rekrutmen relawan Baznaz untuk Iduladha” yang mengarah ke laman tak resmi itu merupakan konten tiruan (impostor content).</li></ul><p>Akun Instagram “info.indonesia_official” pada Selasa (6/5/2025) membagikan <a href="https://www.instagram.com/p/DJUQTERzrI5/?igsh=MXNhbDFweWl6YWx5Yw%3D%3D"><span style="text-decoration: underline;">gambar</span></a> [<a href="https://archive.ph/qlUNB"><span style="text-decoration: underline;">arsip</span></a>] berisi informasi lowongan kerja relawan Iduladha Baznas 2025.</p><p>Berikut narasi lengkapnya:</p><p>“Open Rekrutmen Relawan IDUL ADHA BAZNAS 2025</p><p>• Pendaftaran gratis.&nbsp;</p><p>• Penempatan sesuai domisili pelamar.&nbsp;</p><p>• Gaji 3,7 sampai 5 juta.</p><p>“PENDAFTARAN KLIK LINK DI BIO”</p><p>Hingga Selasa (3/6/2025), unggahan itu menuai 187 tanda suka, ada 5 komentar yang mempertanyakan kebenaran informasi dan menginginkan pekerjaan tersebut.</p><p><strong>Pemeriksaan Fakta</strong></p><p>Tim Pemeriksa Fakta Mafindo (TurnBackHoax) mengakses tautan yang tersemat di bio akun pengunggah. Diketahui, tautan tak mengarah ke laman resmi Badan Amil Zakat Nasional (Baznas) <a href="http://baznas.go.id"><span style="text-decoration: underline;">baznas.go.id</span></a>. Calon pelamar justru diminta mengisi nama lengkap dan nomor telepon yang terhubung dengan Telegram.&nbsp;</p><p>TurnBackHoax lalu menelusuri akun Instagram resmi Baznas, yakni “baznasindonesia”. Diketahui, Baznas lewat salah satu unggahannya telah menegaskan kabar rekrutmen yang beredar adalah informasi palsu.</p><p>“BAZNAS hanya memberikan informasi perihal rekrutmen melalui media sosial dan situs resmi BAZNAS di @baznasindonesia atau <a href="http://baznas.go.id"><span style="text-decoration: underline;">baznas.go.id</span></a>,” tulis Baznas pada Selasa (15/4/2025).</p><p><strong>Kesimpulan</strong></p><p>Unggahan berisi tautan “rekrutmen relawan Baznaz untuk Iduladha” yang mengarah ke laman tak resmi itu merupakan konten tiruan (impostor content).</p><p><strong><em>(Ditulis oleh Rahmah)</em></strong></p>', '2025-06-03 20:57:53', '2025-07-27 21:20:55'),
	(24, '[SALAH] Kuasa Hukum Jokowi Terbata-bata Menjawab Pertanyaan Hakim', 'salah-kuasa-hukum-jokowi-terbata-bata-menjawab-pertanyaan-hakim', 'Aribowo Sasmito', 3, 'verified', 'nasional', 'https://turnbackhoax.id/2025/06/02/salah-kuasa-hukum-jokowi-terbata-bata-menjawab-pertanyaan-hakim/', 'https://turnbackhoax.id/wp-content/uploads/2025/06/phpu-pesawaran-HEADER-326x245.png', '<ul><li>Faktanya, yang berada di video yang dibagikan adalah Jou Hasyim Waimahing di Sidang PHPU Bupati Kabupaten Pesawaran Tahun 2024.</li><li>Unggahan yang membagikan video tersebut masuk ke kategori konten yang menyesatkan (<em>misleading content</em>).</li></ul><p>Pada Kamis (22/5/2025) beredar sebuah <a href="https://x.com/EkoPurwanto001/status/1925343480194428986"><span style="text-decoration: underline;">unggahan</span></a> di X (<a href="https://archive.ph/LAaFd"><span style="text-decoration: underline;">arsip cadangan</span></a>) oleh akun “eko.p” (@EkoPurwanto001)&nbsp; yang membagikan sebuah video dengan narasi:</p><blockquote>“Kuasa hukum Jokowi terbatabata jawab pertanyaan&nbsp;hakim 😂Cuma sampai semester 4berarti gak bisa Wisuda dong”&nbsp;</blockquote><p>dengan menambahkan narasi:&nbsp;</p><blockquote>“💥 TERNYATA, OH TERNYATA.. 🎊🎉Ternyata hanya kuliah sampai semester 4.. lha ya gak bisa punya ijasah (asli) to yak.. 🤣🤣🤭”</blockquote><p>di unggahannya.</p><p>Per arsip cadangan dibuat, unggahan tersebut&nbsp; sudah ditonton 15.2 ribu kali, mendapatkan 27 jawaban, dibagikan ulang 80 kali, dan disukai oleh 181 akun pengguna X lainnya.</p><p><strong>Pemeriksaan Fakta</strong></p><p>Tim Pemeriksa Fakta MAFINDO (TurnBackHoax) menelusuri kebenaran klaim menggunakan mesin pencari video Google Videos dengan kata kunci “sidang pesawaran”, berdasarkan petunjuk dari beberapa jawaban di media sosial X. Disebutkan bahwa selain bukan video sidang kasus ijazah Jokowi, sebenarnya sidang di video yang dibagikan adalah sidang kasus Bupati Kabupaten Pesawaran.&nbsp;</p><p>Hasil pencarian memberikan petunjuk ke beberapa sumber otoritatif, salah satunya oleh akun Mahkamah Konstitusi RI di YouTube di unggahan “(Panel II) Sidang Perkara PHPU Gubernur, Bupati dan Walikota, Senin, 17 Februari 2025.” yang merupakan siaran secara langsung (<em>live streaming</em>).&nbsp;</p><p>Ditemukan juga dokumen risalah sidang yang didapatkan dengan mencari menggunakan kata kunci “Perkara Nomor 20/PHPU.BUP-XXIII/2025”, seperti yang tertera di deskripsi unggahan di YouTube. Selain itu, menggunakan kata kunci “pengacara jokowi kasus ijazah palsu” di perkakas (<em>tools</em>) pencarian berita Google News didapatkan fakta bahwa pengacara kasus ijazah Jokowi adalah Yakup Hasibuan, bukan Jou Hasyim Waimahing.</p><p><strong>Kesimpulan</strong></p><p>Unggahan tersebut masuk ke kategori konten yang menyesatkan (<em>misleading content</em>), faktanya yang berada di video yang dibagikan adalah Jou Hasyim Waimahing di Sidang PHPU Bupati Kabupaten Pesawaran Tahun 2024.&nbsp;</p>', '2025-06-03 20:57:55', '2025-07-27 21:20:24'),
	(25, '[SALAH] Jalanan Macet Total karena Rombongan Prabowo Mau Lewat', 'salah-jalanan-macet-total-karena-rombongan-prabowo-mau-lewat', 'Aribowo Sasmito', 3, 'verified', 'nasional', 'https://turnbackhoax.id/2025/06/02/salah-jalanan-macet-total-karena-rombongan-prabowo-mau-lewat/', 'https://turnbackhoax.id/wp-content/uploads/2025/06/albanese-visit-HEADER-326x245.png', '\n\n\n<ul class="wp-block-list">\n<li>Faktanya, konvoi yang direkam di video adalah rombongan Perdana Menteri Australia Anthony Albanese yang sedang melakukan lawatan resmi ke Indonesia.</li>\n\n\n\n<li>Unggahan yang membagikan video tersebut masuk ke kategori konten yang menyesatkan (<em>misleading content</em>).</li>\n</ul>\n\n\n\n<hr class="wp-block-separator has-alpha-channel-opacity">\n\n\n\n<p class="has-text-align-left">Pada Senin (19/5/2025) beredar sebuah <a href="https://x.com/RamaAdamfaathir/status/1924258669371486332">unggahan</a> di X (<a href="https://archive.ph/wAzvX">arsip cadangan</a>) oleh akun “Rama Adam Faathir 🇮🇩” (@RamaAdamfaathir)&nbsp; yang membagikan sebuah video dengan narasi:</p>\n\n\n\n<blockquote class="wp-block-quote is-layout-flow wp-block-quote-is-layout-flow">\n<p>“Ini kejadian kemarin di area Kuningan Jakarta selatan.</p>\n\n\n\n<p>Hanya karena rombongan @prabowo mau lewat jalanan macet total saat masyarakat pulang kerja.</p>\n\n\n\n<p>Ini kejadian kedua setelah mulyono @jokowi yang disoraki negatif oleh masyarakat sragen , sekarang Prabowo disoraki negatif oleh masyarakat Jakarta.</p>\n\n\n\n<p>Semoga ini jadi tanda2 REVOLUSI SOSIAL ketika masyarakat sudah muak dengan korupsi para pejabatnya yang dipertontonkan secara telanjang di media2 nasional tapi masih bisa petantang petenteng dijalanan.”</p>\n</blockquote>\n\n\n\n<p class="has-text-align-left">di unggahannya.</p>\n\n\n\n\n\n\n\n<p class="has-text-align-left">Per tangkapan layar dibuat ketika artikel ini disusun, unggahan tersebut&nbsp; sudah ditonton 533.6 ribu kali, mendapatkan 542 jawaban, dibagikan ulang 2 ribu kali, dan disukai oleh 5.4 ribu akun pengguna X lainnya.</p>\n\n\n\n<p><span style="background-color: #ff8c00; padding: 3px 8px; font-weight: bold; border-radius: 8px;">Pemeriksaan Fakta</span></p>\n\n\n\n<p>Tim Pemeriksa Fakta MAFINDO (TurnBackHoax) menelusuri kebenaran klaim menggunakan mesin pencari (<em>search engine</em>) Google menggunakan kata kunci “kunjungan perdana menteri albanese”, berdasarkan petunjuk dari laporan melalui <em>mention</em> di media sosial X.&nbsp;</p>\n\n\n\n<p>Hasil pencarian memberikan hasil ke beberapa sumber otoritatif, salah satunya artikel oleh <a href="http://gridoto.com">GridOto.com</a> di artikel “Rombongan PM Australia Lewat, Warga Protes Kena Macet di Kuningan, Begini Kata Polisi”.&nbsp;</p>\n\n\n\n<p>Menggunakan kata kunci yang sama di pencarian berita Google News menghasilkan artikel-artikel dari sumber-sumber otoritatif yang mengkoroborasi mendukung artikel di atas.&nbsp;</p>\n\n\n\n<p>Selain itu, berdasarkan petunjuk dari artikel di atas didapatkan juga informasi dari pihak otoritas di akun Instagram @tmcpoldametro dan @divisihumaspolri.</p>\n\n\n\n<p><span style="background-color: #ff8c00; padding: 3px 8px; font-weight: bold; border-radius: 8px;">Kesimpulan</span></p>\n\n\n\n<p>Unggahan tersebut masuk ke kategori konten yang menyesatkan (<em>misleading content</em>), faktanya konvoi yang direkam di video adalah rombongan Perdana Menteri Australia Anthony Albanese yang sedang melakukan lawatan resmi ke Indonesia.</p>\n\n\n<div class="pagination clear mh-clearfix"> <span class="post-page-numbers current" aria-current="page"><span class="pagelink">1</span></span> <a href="https://turnbackhoax.id/2025/06/02/salah-jalanan-macet-total-karena-rombongan-prabowo-mau-lewat/2/" class="post-page-numbers"><span class="pagelink">2</span></a></div>	', '2025-06-03 20:57:56', '2025-07-27 21:19:52'),
	(26, '[SALAH] Tiongkok Menerobos Blokade Israel Drop Bantuan bagi Gaza', 'salah-tiongkok-menerobos-blokade-israel-drop-bantuan-bagi-gaza', 'Aribowo Sasmito', 10, 'verified', 'nasional', 'https://turnbackhoax.id/2025/06/02/salah-tiongkok-menerobos-blokade-israel-drop-bantuan-bagi-gaza/', 'https://turnbackhoax.id/wp-content/uploads/2025/06/X-cn-gaza-airdrop-HEADER-326x245.png', '<ul><li>Faktanya, potongan video yang disebarkan diambil dari latihan gabungan “Eagles of Civilization 2025” antara Angkatan Udara Tiongkok dengan Mesir.&nbsp;</li><li>Unggahan yang membagikan video tersebut masuk ke kategori konten yang menyesatkan (<em>misleading content</em>).</li></ul><p>Pada Rabu (14/5/2025) beredar sebuah <a href="https://x.com/anneserlo/status/1922472775110844883"><span style="text-decoration: underline;">unggahan</span></a> di X (<a href="https://archive.md/YgabD"><span style="text-decoration: underline;">arsip cadangan</span></a>) oleh akun “anne serlo” (@anneserlo)&nbsp; yang membagikan sebuah video dengan narasi:</p><blockquote>“China🇨🇳 Terobos Blokade Israel🇮🇱Untuk Kirimkan Bantuan UntukPalestina🇵🇸” Hingga GemparkanDunia ‼️”&nbsp;</blockquote><p>dengan menambahkan narasi:</p><blockquote>“HANYA CINA YANG BERANI BEGINIHanya Cina yang berani menerobos blokade Israel dan mendrop bantuan kemanusiaan bagi Gaza.Sayang, menurut teman saya, sebaik-baiknya kafir, akan tetap masuk neraka.”</blockquote><p>di sebarannya.</p><p>Per tangkapan layar dibuat ketika artikel ini disusun, unggahan tersebut sudah ditonton 463 kali, mendapatkan 4 jawaban, dibagikan ulang 3 kali, dan disukai oleh 13 akun pengguna X lainnya.</p><p><strong>Pemeriksaan Fakta</strong></p><p>Tim Pemeriksa Fakta MAFINDO (TurnBackHoax) menelusuri kebenaran klaim menggunakan perkakas <em>(tool)</em> InVID WeVerify yang memfragmentasi video ke dalam bentuk gambar/foto untuk mencari bingkai utama (<em>Keyframe</em>), yang kemudian digunakan untuk melakukan pencarian gambar (<em>image search</em>) menggunakan Google Lens.&nbsp;</p><p>Hasil pencarian gambar menggunakan Keyframe #1 tidak membantu karena yang ditemukan justru sumber-sumber pelintiran yang diunggah oleh akun-akun di berbagai platform media sosial. Menggunakan formasi terbang di atas Piramid yang muncul di segmen awal video sebagai petunjuk untuk menjalankan pencarian menggunakan Google Videos dan YouTube dengan kata kunci “china air force egypt”, hasilnya mengarahkan ke kegiatan latihan gabungan “Eagles of Civilization 2025” antara Angkatan Udara Tiongkok dengan Mesir.&nbsp;</p><p>Menggunakan kata kunci “eagles of civilization 2025” di pencarian video Google Videos dan pencarian berita Google News menghasilkan video, artikel dan berita dari berbagai sumber otoritatif, salah satunya dari Kementerian Pertahanan Tiongkok di rilis “Latihan gabungan angkatan udara Tiongkok-Mesir “Eagles of Civilization 2025” berakhir” (terjemahan oleh Google Translate). Kegiatan ini berlangsung selama 18 hari, yang berakhir pada hari Minggu (4/5/2025) lalu. Sumber-sumber otoritatif hasil pencarian Google News yang lainnya juga mengkoroborasi mendukung rilis dari Kementerian Pertahanan Tiongkok tersebut.&nbsp;</p><p>Untuk segmen video lainnya yang memperlihatkan penerjunan bantuan menggunakan parasut, pencarian menggunakan Keyframe #31 juga tidak membantu karena hasil yang ditemukan adalah sumber-sumber pelintiran yang diunggah oleh akun-akun di berbagai platform media sosial, sama seperti hasil pencarian segmen video yang sebelumnya.&nbsp;</p><p>Pencarian di Google Videos dan YouTube menggunakan kata kunci “gaza aid airdrop” menghasilkan video dari sumber-sumber otoritatif. Meskipun ditemukan berita terbitan tahun ini (2025) mengenai otoritas Yordania yang disebut mengambil keuntungan dari penerjunan bantuan ke Gaza, sumber-sumber ini menginformasikan bahwa peristiwa penerjunan bantuan terjadi pada tahun lalu (2024). Artinya, segmen video penerjunan bantuan tidak mendukung klaim yang mengaitkan dengan klaim di segmen video pertama seperti bantahan sebagian pengguna media sosial dengan premis salah “Iya memang ini bantuannya dikirim lewat Mesir, makanya kelihatan terbang di atas Piramid”. Klaim menggunakan video rekaman peristiwa yang berlangsung pada tahun ini (2025) tentu saja tidak bisa dirangkai dengan rekaman peristiwa yang terjadi pada tahun lalu (2024), karena tidak nyambung.</p><p><strong>Kesimpulan</strong></p><p>Unggahan tersebut masuk ke kategori konten yang menyesatkan (<em>misleading content</em>), faktanya potongan video yang disebarkan diambil dari latihan gabungan “Eagles of Civilization 2025” antara Angkatan Udara Tiongkok dengan Mesir.</p>', '2025-06-03 20:57:57', '2025-07-27 21:22:51'),
	(27, '[SALAH] Video “Tentara India Kibarkan Bendera Putih ke Pakistan”', 'salah-video-tentara-india-kibarkan-bendera-putih-ke-pakistan', 'Pemeriksa Fakta Junior', 1, 'verified', 'nasional', 'https://turnbackhoax.id/2025/06/02/salah-video-tentara-india-kibarkan-bendera-putih-ke-pakistan/', 'https://turnbackhoax.id/wp-content/uploads/2025/06/HEADER-Light-Background-8-326x245.png', '\n\n\n<ul class="wp-block-list">\n<li>Konteks asli video adalah momen tentara Pakistan mengibarkan bendera putih sebagai permintaan gencatan senjata sementara pada September 2019.</li>\n\n\n\n<li>Unggahan berisi klaim “pasukan India mengibarkan bendera putih ke tentara Pakistan” merupakan konten yang menyesatkan (misleading content).</li>\n</ul>\n\n\n\n<hr class="wp-block-separator has-alpha-channel-opacity">\n\n\n\n<p>Akun X “PecintaSejarah2” pada Kamis (8/5/2025) mengunggah <a href="https://x.com/PecintaSejarah2/status/1920368795937615971">video</a> [<a href="https://archive.ph/Pq6ig">arsip</a>] rekaman pasukan tentara mengibarkan bendera putih.&nbsp;</p>\n\n\n\n<p>Unggahan disertai narasi:</p>\n\n\n\n<blockquote class="wp-block-quote is-layout-flow wp-block-quote-is-layout-flow">\n<p>“Momen ketika pasukan India mengibarkan bendera putih, mereka memohon kepada tentara Pakistan agar diberi kesempatan untuk mengevakuasi rekan-rekannya yang tewas akibat pertempuran di perbatasan antara kedua negara.</p>\n\n\n\n<p>Dalam video tersebut terlihat pasukan Pakistan tidak melakukan tembakan saat proses evakuasi. Situasi akan berbeda jika pasukan Pakistan berada dalam posisi tentara India”.</p>\n</blockquote>\n\n\n\n\n\n\n\n<p>Hingga Senin (2/6/2025) unggahan telah ditonton 24 ribu kali, dibagikan ulang 121 kali, dan disukai 405 akun.&nbsp;</p>\n\n\n\n<p><span style="background-color: #ff8c00;padding: 3px 8px;font-weight: bold;border-radius: 8px">Pemeriksaan Fakta</span></p>\n\n\n\n<p>Disadur dari artikel Cek Fakta <a href="https://www.antaranews.com/berita/4825929/cek-fakta-video-tentara-india-kibarkan-bendera-putih-ke-pakistan">antaranews.com.</a></p>\n\n\n\n<p>ANTARA melakukan penelusuran dengan perangkat Google Lens, ditemukan banyak berita dengan foto serupa salah satunya berita berjudul “Fact Check: 2019 video of Pak soldiers waving white flag NOW being pushed as Indian troops!” yang dirilis oleh media asal India, India Today.</p>\n\n\n\n<p>Video tersebut sebenarnya diambil pada September 2019 saat tentara Pakistan mengibarkan bendera putih sebagai permintaan gencatan senjata sementara, untuk mengevakuasi rekan mereka yang gugur di medan perang yang terletak di perbatasan kedua negara, tepatnya sepanjang Garis Kontrol (LoC).</p>\n\n\n\n<p><span style="background-color: #ff8c00;padding: 3px 8px;font-weight: bold;border-radius: 8px">Kesimpulan</span></p>\n\n\n\n<p>Unggahan berisi klaim “pasukan India mengibarkan bendera putih ke tentara Pakistan” merupakan konten yang menyesatkan (misleading content).</p>\n\n\n\n<p><strong>(</strong><strong><em>Ditulis oleh Zahra</em></strong><strong>)</strong></p>\n\n\n<div class="pagination clear mh-clearfix"> <span class="post-page-numbers current" aria-current="page"><span class="pagelink">1</span></span> <a href="https://turnbackhoax.id/2025/06/02/salah-video-tentara-india-kibarkan-bendera-putih-ke-pakistan/2/" class="post-page-numbers"><span class="pagelink">2</span></a></div>	', '2025-06-03 20:57:59', '2025-06-03 20:57:59'),
	(28, '[SALAH] Prabowo Resmi Copot Gibran', 'salah-prabowo-resmi-copot-gibran', 'Pemeriksa Fakta Junior', 3, 'verified', 'nasional', 'https://turnbackhoax.id/2025/06/02/salah-prabowo-resmi-copot-gibran/', 'https://turnbackhoax.id/wp-content/uploads/2025/06/HEADER-Dark-Background-12-326x245.png', '<ul><li>Tidak ada keterangan resmi atau pemberitaan kredibel yang membenarkan klaim.&nbsp;</li><li>Unggahan berisi narasi “Presiden Prabowo resmi copot Gibran dan umumkan penggantinya” merupakan konten yang menyesatkan (misleading content).&nbsp;</li></ul><p>Akun YouTube “KajianOnline” pada Selasa (29/4/2025) mengunggah <a href="https://www.youtube.com/watch?v=pAWzVjuNt6k"><span style="text-decoration: underline;">video</span></a> [<a href="https://archive.ph/J5f9V"><span style="text-decoration: underline;">arsip</span></a>] berdurasi 8 menit 51 detik dengan narasi:</p><blockquote>“Jokowi PINGSAN ! Prabowo Resmi Copot Gibran ! Presiden Umumkan Penganti Wapres~ PDIP Ajukan PUAN !”.</blockquote><p>Hingga Senin (2/6/2025) unggahan tersebut telah ditonton lebih dari 26 ribu kali dan disukai 405 akun.&nbsp;</p><p><strong>Pemeriksaan Fakta</strong></p><p>Tim Pemeriksa Fakta Mafindo (TurnBackHoax) memasukkan kata kunci “Prabowo resmi copot Gibran” ke mesin pencari Google. Penelusuran teratas mengarah ke sejumlah artikel yang membantah klaim, yakni:</p><ul><li><a href="https://www.antaranews.com/berita/4809541/hoaks-prabowo-resmi-copot-wakil-presiden-pada-akhir-april"><span style="text-decoration: underline;">antaranews.com</span></a> “Hoaks! Prabowo resmi copot wakil presiden pada akhir April” yang tayang pada Jumat (2/5/2025), dan</li><li><a href="https://www.kompas.tv/regional/594657/hoax-presiden-prabowo-resmi-copot-gibran-sebagai-wakil-presiden-news-or-hoax"><span style="text-decoration: underline;">kompas.tv</span></a> “Hoax Presiden Prabowo Resmi Copot Gibran Sebagai Wakil Presiden | NEWS OR HOAX” yang tayang pada Rabu (21/5/2025).</li></ul><p>TurnBackHoax juga mengakses <a href="https://setkab.go.id/"><span style="text-decoration: underline;">laman resmi</span></a> Sekretariat Kabinet Republik Indonesia, <a href="http://setkab.go.id"><span style="text-decoration: underline;">setkab.go.id</span></a>. Hasilnya, tidak ditemukan nama wakil presiden baru di susunan Kabinet Merah Putih.&nbsp;</p><p>TurnBackHoax lalu mencari tahu konteks asli foto yang digunakan dalam foto sampul (thumbnail) dengan memanfaatkan Google Lens. Foto yang dipergunakan berasal dari sejumlah media, yakni:</p><ul><li><a href="https://www.antarafoto.com/id/view/2502873/presiden-lantik-gubernur-wakil-gubernur-papua-pegunungan-dan-bangka-belitung"><span style="text-decoration: underline;">antarafoto.com</span></a> “Presiden lantik Gubernur-Wakil Gubernur Papua Pegunungan dan Bangka Belitung” yang diunggah pada Kamis (17/4/2025),</li><li><a href="http://cnnindonesia.com"><span style="text-decoration: underline;">cnnindonesia.com</span></a> “Ahli Sentil ‘Gunung Utang’ Jokowi: 2025 Prabowo Harus Bayar Rp1.353 T” yang tayang pada Minggu (18/8/2024), dan</li><li><a href="https://news.republika.co.id/berita/nb12zl/soal-ketua-dpr-puan-tunggu-sidang-mk"><span style="text-decoration: underline;">news.republika.co.id</span></a> “Soal Ketua DPR, Puan Tunggu Sidang MK” yang tayang pada Jumat (29/8/2014).</li></ul><p>Terlihat di ketiga sumber tersebut bahwa ketiga foto tersebut berasal dari tiga kejadian berbeda yang terjadi di waktu yang berbeda-beda, serta ketiganya tidak berhubungan dengan dicopotnya Gibran dari kursi wakil presiden.&nbsp;</p><p>Lebih lanjut, isi dari video berdurasi 8 menit 51 detik tersebut hanya berisi narasi sesuai judul tanpa ada cuplikan pernyataan Presiden Prabowo yang secara resmi memakzulkan Gibran pada akhir April 2025.&nbsp;</p><p><strong>Kesimpulan</strong></p><p>Unggahan berisi narasi “Presiden Prabowo resmi copot Gibran dan umumkan penggantinya” merupakan konten yang menyesatkan (misleading content).&nbsp;</p><p><strong>(</strong><strong><em>Ditulis oleh Zahra</em></strong><strong>)</strong></p>', '2025-06-03 20:58:00', '2025-07-27 21:18:31'),
	(29, '[PENIPUAN] Tautan Pendaftaran Lowongan Kerja Mandiri Taspen', 'penipuan-tautan-pendaftaran-lowongan-kerja-mandiri-taspen', 'Relawan Mafindo', 7, 'verified', 'nasional', 'https://turnbackhoax.id/2025/06/02/penipuan-tautan-pendaftaran-lowongan-kerja-mandiri-taspen/', 'https://turnbackhoax.id/wp-content/uploads/2025/06/lokeer-326x245.jpg', '<ul><li>Tidak terdapat informasi yang valid mengenai loker tersebut. Mandiri Taspen saat ini tidak memiliki lowongan aktif.</li><li>Unggahan berisi tautan “pendaftaran lowongan kerja Mandiri Taspen” yang mengarah ke laman tak resmi itu merupakan konten palsu (fabricated content).</li></ul><p>Akun TikTok “warga62info” pada Sabtu (5/4//2025) mengunggah <a href="https://www.tiktok.com/@warga62info/photo/7489820451514879250"><span style="text-decoration: underline;">video </span></a>[<a href="https://archive.md/677Zo"><span style="text-decoration: underline;">arsip</span></a>] berisi informasi lowongan kerja di Bank Mandiri Taspen. Berikut narasinya:</p><blockquote>“LOWONGAN KERJA PT BANK MANDIRI TASPEN<br>UNTUK LULUSAN SMA, SMK, D3, DAN S1<br>Berikut Persyaratan Pendaftarannya:<ul><li>Pendidikan SMA SMK D3 S1 sederajat</li><li>Lowongan terbuka untuk berbagai jurusan</li><li>Pria dan Wanita dengan usia maksimal 45 tahun</li><li>Fresh Graduate dipersilahkan untuk mendaftarkan diri</li><li>Memiliki keterampilan komunikasi yang baik serta service-oriented</li><li>Lokasi penempatan di berbagai kota dan kabupaten<br>Keuntungan:</li><li>Gaji Rp 5,5 juta – Rp 10 juta</li><li>BPJS Lengkap</li><li>Jenjang karir yang bagus<br>Informasi selengkapnya silakan klik link di bio.</li></ul></blockquote><p>Hingga Senin (26/5/2025), unggahan telah disukai lebih dari 900-an akun, dibagikan ulang 323 kali, serta menuai 268 komentar.</p><p><strong>Pemeriksaan Fakta</strong></p><p>Tim Pemeriksa Fakta Mafindo (TurnBackHoax) memasukkan kata kunci “loker PT Mandiri Taspen” ke mesin pencarian Google. Penelusuran teratas mengarah ke laman resmi Bank Mandiri Taspen (<a href="http://bankmandiritaspen.co.id"><span style="text-decoration: underline;">bankmandiritaspen.co.id</span></a>).</p><p>Penelusuran berlanjut ke kanal “Karier” di laman tersebut. Diketahui, Mandiri Taspen tidak memiliki lowongan aktif.</p><p>TurnBackHoax kemudian mengakses tautan dalam unggahan akun TikTok “warga62info”. Tautan mengarah ke laman yang meminta pengisian data pribadi berupa nama lengkap dan nomor Telegram aktif.</p><p><strong>Kesimpulan</strong></p><p>Unggahan berisi tautan “pendaftaran lowongan kerja Mandiri Taspen” yang mengarah ke laman tak resmi itu merupakan konten palsu (fabricated content).</p><p><strong><em>(Ditulis oleh Vinanda Febriani)</em></strong></p>', '2025-06-03 20:58:01', '2025-07-27 21:18:08'),
	(30, '[PENIPUAN] Video “Dedi Mulyadi Mau Bagi-Bagi Uang Tunai”', 'penipuan-video-dedi-mulyadi-mau-bagi-bagi-uang-tunai', 'Pemeriksa Fakta Junior', 3, 'verified', 'nasional', 'https://turnbackhoax.id/2025/06/02/penipuan-video-dedi-mulyadi-mau-bagi-bagi-uang-tunai/', 'https://turnbackhoax.id/wp-content/uploads/2025/06/Header-KDM-Bagi-uang-326x245.png', '<ul><li>Konten itu hasil rekayasa AI. Konteks asli video adalah momen ketika Dedi Mulyadi menjelaskan perlunya penegakan hukum yang transparan dalam kasus penembakan bos rental mobil oleh anggota TNI AL.</li><li>Unggahan video berisi klaim “Dedi Mulyadi mau bagi-bagi uang tunai” merupakan konten palsu (fabricated content).</li></ul><p>Akun Facebook “Kailasari Utama” pada Selasa (22/4/2025) membagikan <a href="https://www.facebook.com/reel/721311333802121"><span style="text-decoration: underline;">video</span></a> [<a href="https://turnbackhoax.id/wp-content/uploads/2025/05/Arsip-Dedi-Mulyadi-Bagi-20-Juta-scaled.png"><span style="text-decoration: underline;">arsip</span></a>], isinya memperlihatkan Gubernur Jawa Barat Dedi Mulyadi yang mengatakan ingin bagi-bagi uang.</p><p>Berikut narasi yang diucapkan Dedi Mulyadi dalam video:</p><blockquote>“Assalamualaikum, saya Dedi Mulyadi, alhamdulillah saya sekarang sudah terpilih menjadi Gubernur Jawa Barat, dan sebagai rasa terima kasih kepada semua rakyat Indonesia khususnya Jawa Barat, saya akan memberikan bantuan sebesar 20.000.000 perorang. Bantuan ini akan saya berikan bagi yang sudah follow dan share video ini. Ingat ini adalah nazar dari saya ya, dan jika kamu sudah menerima bantuan dari saya jangan untuk berfoya-foya ya. Terima kasih.”</blockquote><p>Hingga Senin (2/6/2025) unggahan tersebut telah disukai 470 pengguna dan menuai 260 komentar yang mayoritas mempercayai video tersebut.</p><p><strong>Pemeriksaan Fakta</strong></p><p>Tim Pemeriksa Fakta Mafindo (TurnBackHoax) menonton video itu dari awal hingga akhir. Terlihat kalau ada sejumlah gerak bibir dan ekspresi Dedi Mulyadi yang terlihat kaku dan tidak alami.</p><p>TurnBackHoax kemudian mengunduh video tersebut dan mengunggahnya ke alat pendeteksi AI dari Hive Moderation. <a href="https://turnbackhoax.id/wp-content/uploads/2025/05/Arsip-hasil-deteksi-AI-Dedi-Mulyadi.png"><span style="text-decoration: underline;">Diketahui,</span></a> konten tersebut merupakan hasil rekayasa AI, probabilitas atau kemungkinannya mencapai 99,8 persen.</p><p>TurnBackHoax kemudian menelusuri potongan gambar dari video unggahan akun Facebook “Kailasari Utama” tersebut dengan bantuan Google Lens. <a href="https://turnbackhoax.id/wp-content/uploads/2025/05/Hasil-Penelusuran-Google-Lens-video-Dedi-Mulyadi.png"><span style="text-decoration: underline;">Hasil penelusuran</span></a> mengarah ke video serupa yang diunggah akun TikTok resmi Dedi Mulyadi, “<a href="https://www.tiktok.com/@dedimulyadiofficial/video/7457146523147635973"><span style="text-decoration: underline;">dedimulyadiofficial</span></a>”.&nbsp;</p><p>Dalam video tersebut Dedi Mulyadi menjelaskan tentang perlunya penegakan hukum yang transparan dalam kasus penembakan bos rental mobil oleh anggota TNI AL.</p><p><strong>Kesimpulan</strong></p><p>Unggahan video berisi klaim “Dedi Mulyadi mau bagi-bagi uang tunai” merupakan konten palsu (fabricated content).</p><p><strong><em>(Ditulis oleh Moch. Marcellodiansyah)</em></strong></p>', '2025-06-03 20:58:03', '2025-07-27 21:17:38'),
	(31, '[SALAH] Kemenkes Wajibkan Penumpang Pesawat Tervaksinasi TBC', 'salah-kemenkes-wajibkan-penumpang-pesawat-tervaksinasi-tbc', 'Pemeriksa Fakta Junior', 2, 'verified', 'nasional', 'https://turnbackhoax.id/2025/05/31/salah-kemenkes-wajibkan-penumpang-pesawat-tervaksinasi-tbc/', 'https://turnbackhoax.id/wp-content/uploads/2025/05/header-kemekes-wajibkan-vaksin-tbc-326x245.png', '<ul><li>Kemenkes telah membantah narasi tersebut.</li><li>Unggahan berisi klaim “Kemenkes wajibkan penumpang pesawat tervaksinasi TBC” merupakan konten yang menyesatkan (misleading content).</li></ul><p>Akun X “HumorJonTampan” pada Senin (26/5/2025) membagikan <a href="https://x.com/HumorJonTampan/status/1926950387384205608"><span style="text-decoration: underline;">foto</span></a> [<a href="https://archive.ph/x2P94"><span style="text-decoration: underline;">arsip</span></a>] berisi klaim:</p><blockquote>“Kemenkes: Semua penumpang yang akan naik pesawat agar sudah divaksin TBC dan menunjukan surat vaksin. tujuannya untuk mencegah penyebaran lewat udara. Budi Gunadi Sadikin, Menkes.”</blockquote><p>Pengunggah menyertakan narasi berikut dalam takarirnya:</p><blockquote>“‘Hemmmmm…. Sales obat Bill Gates sudah mulai bekerja kah ini??’”</blockquote><p>Hingga Sabtu (31/5/2025) unggahan telah disukai 6.000 pengguna dan dibagikan ulang 1.000 kali.</p><p><strong>Pemeriksaan Fakta</strong></p><p>Disadur dari pemberitaan <a href="https://www.detik.com/kalimantan/berita/d-7929238/kemenkes-bantah-vaksin-tbc-bill-gates-jadi-syarat-wajib-perjalanan"><span style="text-decoration: underline;">detik.com</span></a></p><p>Kementerian Kesehatan dalam keterangan resminya telah menegaskan bahwa narasi tersebut tidak benar.</p><p>“Tidak ada aturan yang mewajibkan vaksin TBC untuk naik pesawat,” tulis Kemenkes RI dalam keterangan resminya.</p><p>Vaksin TBC M72 yang dikembangkan dengan pendanaan dari Gates Foundation hingga kini belum diwajibkan karena masih dalam tahap uji klinis fase tiga. Vaksin ini juga belum digunakan secara luas.</p><p>Di Indonesia, proses uji coba vaksin tersebut melibatkan lebih dari 2.000 partisipan yang terus dipantau untuk melihat efektivitas vaksin dalam jangka waktu 3 hingga 4 tahun sejak penyuntikan pertama pada November 2024.&nbsp;</p><p><strong>Kesimpulan</strong></p><p>Unggahan berisi klaim “Kemenkes wajibkan penumpang pesawat tervaksinasi TBC” merupakan konten yang menyesatkan (misleading content).</p><p><strong><em>(Ditulis oleh Moch. Marcellodiansyah)</em></strong></p>', '2025-06-03 20:58:04', '2025-07-27 21:17:11'),
	(32, '[PENIPUAN] Tautan “Pendaftaran Beasiswa Guru Fullbright DAI”', 'penipuan-tautan-pendaftaran-beasiswa-guru-fullbright-dai', 'Pemeriksa Fakta Junior', 7, 'verified', 'nasional', 'https://turnbackhoax.id/2025/05/31/penipuan-tautan-pendaftaran-beasiswa-guru-fullbright-dai/', 'https://turnbackhoax.id/wp-content/uploads/2025/05/header-beasiswa-fullbright-326x245.png', '<ul><li>Pendaftaran Fullbright DAI secara daring hanya dapat dilakukan lewat <a href="http://fulbright.irex.org"><span style="text-decoration: underline;">fulbright.irex.org</span></a>, <a href="http://irex.org/fulbright-dai"><span style="text-decoration: underline;">irex.org/fulbright-dai</span></a>, atau<a href="http://www.fulbrightteacherexchanges.org"><span style="text-decoration: underline;"> fulbrightteacherexchanges.org</span></a>.</li><li>Unggahan berisi tautan “pendaftaran beasiswa guru Fullbright DAI” merupakan konten palsu (fabricated content).</li></ul><p>Akun Facebook “Program Beasiswa” pada Selasa (22/4/2025) membagikan <a href="https://www.facebook.com/permalink.php?story_fbid=pfbid02LzHTAVhb1jfbqpJTC8HoPmskzDNF18FfzfFU6xk9Cx8E57VWBdcFtFP2vTc74Ydzl&amp;id=61574117815589&amp;rdid=QpJKtDTWVNO16cBs"><span style="text-decoration: underline;">tautan</span></a> [<a href="https://archive.ph/L4NBP"><span style="text-decoration: underline;">arsip</span></a>] disertai narasi:</p><blockquote>“Beasiswa Guru 2025 – 2026 untuk SD, SMP, SMA, dan Sederajat: Fulbright DAI 💡 Deskripsi: Apakah kamu seorang guru SD, SMP, SMA, atau sederajat yang ingin mengembangkan diri sekaligus mengeksplorasi pengalaman internasional? Program Fulbright Distinguished Awards in Teaching Program for International Teachers (Fulbright DAI) adalah jawabannya! Bayangkan, kamu bisa kuliah selama satu semester di universitas ternama di Amerika Serikat, mengembangkan proyek individu atau kelompok yang bisa bermanfaat bagi karier dan sekolahmu, serta berbagi ilmu dan pengalaman dengan guru serta siswa di sekolah dasar hingga menengah di AS. Tertarik? Jangan sampai ketinggalan!Beasiswa Guru 2025 – 2026 untuk SD, SMP, SMA, dan Sederajat: Fulbright DAI 💡 Deskripsi: Apakah kamu seorang guru SD, SMP, SMA, atau sederajat yang ingin mengembangkan diri sekaligus mengeksplorasi pengalaman internasional? Program Fulbright Distinguished Awards in Teaching Program for International Teachers (Fulbright DAI) adalah jawabannya! Bayangkan, kamu bisa kuliah selama satu semester di universitas ternama di Amerika Serikat, mengembangkan proyek individu atau kelompok yang bisa bermanfaat bagi karier dan sekolahmu, serta berbagi ilmu dan pengalaman dengan guru serta siswa di sekolah dasar hingga menengah di AS. Tertarik? Jangan sampai ketinggalan!”</blockquote><p>Hingga Sabtu (31/5/2025) unggahan tersebut telah disukai oleh hampir 100 pengguna.</p><p><strong>Pemeriksaan Fakta</strong></p><p>Tim Pemeriksa Fakta Mafindo (TurnBackHoax) memasukkan kata kunci “Fulbright DAI” ke mesin pencari Google. Hasil penelusuran mengarah ke laman resmi American Indonesian Exchange Foundation (AMINEF) di alamat <a href="https://www.aminef.or.id/grants-for-indonesians/fulbright-programs/fellowships/fulbright-dai/"><span style="text-decoration: underline;">aminef.or.id</span></a>.</p><p>Berdasarkan informasi di laman tersebut, pendaftaran beasiswa Fulbright DAI dilakukan dengan mengirimkan dokumen ke kantor AMINEF yang berlokasi di Intiland Tower, Lantai 11, Jalan Jenderal Sudirman Kav. 32, Jakarta. Pendaftaran daring hanya bisa dilakukan melalui tautan resmi seperti <a href="http://fulbright.irex.org"><span style="text-decoration: underline;">fulbright.irex.org</span></a>, <a href="http://irex.org/fulbright-dai"><span style="text-decoration: underline;">irex.org/fulbright-dai</span></a>, atau<a href="http://www.fulbrightteacherexchanges.org"><span style="text-decoration: underline;"> fulbrightteacherexchanges.org</span></a>.</p><p>Tim TurnBackHoax kemudian menelusuri tautan yang dibagikan oleh akun Facebook “Program Beasiswa”. Tautan tersebut tidak mengarah ke laman resmi yang disebutkan AMINEF, melainkan ke halaman yang meminta data pribadi seperti nama lengkap, provinsi asal, usia, jenis kelamin, dan nomor Telegram aktif. Saat proses dilanjutkan, pengguna diminta memasukkan kode OTP dari aplikasi Telegram.</p><p><strong>Kesimpulan</strong></p><p>Unggahan berisi tautan “pendaftaran beasiswa guru Fullbright DAI” merupakan konten palsu (fabricated content).</p><p><strong><em>(Ditulis oleh Moch. Marcellodiansyah)</em></strong></p>', '2025-06-03 20:58:05', '2025-07-27 21:16:06'),
	(33, '[PENIPUAN] Tautan “Rekrutmen Pemadam Kebakaran”', 'penipuan-tautan-rekrutmen-pemadam-kebakaran', 'Pemeriksa Fakta Junior', 10, 'verified', 'nasional', 'https://turnbackhoax.id/2025/05/31/penipuan-tautan-rekrutmen-pemadam-kebakaran/', 'https://turnbackhoax.id/wp-content/uploads/2025/05/header-loker-pemadam-kebakaran-326x245.png', '<ul><li>Pendaftaran Pemadam Kebakaran untuk status kepegawaian honorer dapat datang langsung ke kantor Dinas Pemadam Kebakaran, sementara untuk status kepegawaian PNS dan PPPK dilakukan melalui laman resmi <a href="https://sscasn.bkn.go.id/"><span style="text-decoration: underline;">sscasn.bkn.go.id</span></a>.</li><li>Unggahan berisi tautan “rekrutmen pemadam kebakaran” merupakan konten palsu (fabricated content).</li></ul><p>Akun TikTok “info.loker112” pada Jumat (9/5/2025) membagikan <a href="https://www.tiktok.com/@info.loker112/video/7502270149504912695"><span style="text-decoration: underline;">video</span></a> [<a href="https://archive.ph/Os7HW"><span style="text-decoration: underline;">arsip</span></a>] berisi informasi pendaftaran open rekrutmen pemadam kebakaran melalui tautan yang disematkan dalam bio akun tersebut.</p><p>Berikut narasi lengkapnya:</p><blockquote>“Open Rekrutmen Pemadam Kebakaran 2025.&nbsp;Persyaratan:– Pendidikan Minimal SMA/K Sederajat,&nbsp;– Usia 18-30 Tahun,&nbsp;– Memiliki kondisi fisik yang kuat,&nbsp;– Memiliki surat keterangan seat dari Dokter/Puskesmas,&nbsp;– Memiliki Surat Keterangan Catatan Kepolisian (SKCK),&nbsp;– Terbuka untuk non pengalaman dan lulusan baru.&nbsp;Posisi:&nbsp;– Staf Kantor,&nbsp;– Staf Lapangan.”</blockquote><p>Hingga Sabtu (31/5/2025) unggahan tersebut telah disukai oleh hampir 2.000 pengguna dan menuai 41 komentar.</p><p><strong>Pemeriksaan Fakta</strong></p><p>Tim Pemeriksa Fakta Mafindo (TurnBackHoax) memasukkan kata kunci “Bagaimana proses rekrutmen pemadam kebakaran?” ke kolom pencarian Google. Hasil penelusuran teratas mengarah ke artikel dari platform pencari kerja <a href="https://dealls.com/pengembangan-karir/cara-daftar-damkar"><span style="text-decoration: underline;">dealls.com</span></a> “Cara Daftar Damkar 2025: Syarat &amp; Gaji untuk Honorer, PPPK, PNS”.</p><p>Dari artikel yang tayang Maret 2025 itu diketahui kalau pendaftaran kerja pemadam kebakaran berbeda-beda berdasarkan status kepegawaian. Untuk status kepegawaian kontrak atau honorer dapat datang langsung ke kantor Dinas Pemadam Kebakaran dengan memberikan berkas persyaratan ke petugas pendaftaran. Sementara untuk status kepegawaian PNS dan PPPK dilakukan melalui laman resmi <a href="https://sscasn.bkn.go.id/"><span style="text-decoration: underline;">sscasn.bkn.go.id</span></a>.</p><p>TurnBackHoax kemudian mengakses tautan yang disematkan pada bio akun TikTok “info.loker112”. Tautan mengarah ke laman pengisian formulir yang meminta data nama lengkap, nomor aktif Telegram, jenis kelamin, dan pendidikan terakhir. Setelah data dikirim, tautan mengarah ke laman yang meminta kode OTP.&nbsp;</p><p><strong>Kesimpulan</strong></p><p>Unggahan berisi tautan “rekrutmen pemadam kebakaran” merupakan konten palsu (fabricated content).</p><p><strong><em>(Ditulis oleh Moch. Marcellodiansyah)</em></strong></p>', '2025-06-03 20:58:07', '2025-07-27 21:15:29'),
	(34, '[SALAH] Ada Racun Disebarkan dengan Chemtrail, Sebabkan TBC', 'salah-ada-racun-disebarkan-dengan-chemtrail-sebabkan-tbc', 'Pemeriksa Fakta Junior', 2, 'verified', 'nasional', 'https://turnbackhoax.id/2025/05/31/salah-ada-racun-disebarkan-dengan-chemtrail-sebabkan-tbc/', 'https://turnbackhoax.id/wp-content/uploads/2025/05/header-chemtrail-sebabkan-TBC-326x245.png', '<ul><li>Jejak putih yang terlihat di langit setelah pesawat melintas sebenarnya adalah contrail, singkatan dari condensation trail, bukan racun yang disebarkan melalui udara.</li><li>Unggahan berisi klaim “ada racun disebarkan dengan chemtrail, sebabkan TBC” merupakan konten yang menyesatkan (misleading content).</li></ul><p>Akun X “Boediantar4” pada Jumat (9/5/2025) membagikan <a href="https://x.com/Boediantar4/status/1923343651830215068"><span style="text-decoration: underline;">unggahan</span></a> [<a href="https://archive.ph/pAzjS"><span style="text-decoration: underline;">arsip</span></a>] berisi klaim yang menyebut racun disebarkan dengan chemtrail yang dapat menyebabkan batuk, pilek, dan meriang.&nbsp;</p><p>Berikut narasi lengkapnya:</p><blockquote>“Selalu Perhatikan Langit Kita… Chemtrail / racun di Sebar , ga lama batuk2 , pilek , meriang , klo dlu di Vonis c19 , skrg bakal di vonis TBC 🤣…Ada gejala ga ada gejala Kalian di Vonis TB. Ingat dlu 99% yg Meninggal di COVID kan , semua Wafat di RUMAH SAKIT!! think smart”“Waspada bisnis pandemi julid 2”</blockquote><p>Hingga Sabtu (31/5/2025) unggahan tersebut telah disukai oleh 2.000 pengguna dan dibagikan ulang 1.000 kali.</p><p><strong>Pemeriksaan Fakta</strong></p><p>Disadur dari artikel Cek Fakta <a href="https://www.kompas.com/cekfakta/read/2025/05/17/143300382/-hoaks-tbc-disebarkan-lewat-langit-menggunakan-pesawat"><span style="text-decoration: underline;">kompas.com</span></a>.</p><p>Klaim terkait pesawat digunakan untuk menyebarkan zat kimia beracun ke udara merupakan teori konspirasi lama yang telah dibantah oleh para pakar dan akademisi.</p><p>Menurut penjelasan para ahli, jejak putih yang terlihat di langit setelah pesawat melintas sebenarnya adalah contrail, singkatan dari condensation trail. Ini merupakan fenomena yang biasa terjadi akibat perbedaan suhu dan kadar uap air di atmosfer.</p><p>Dilansir dari <a href="https://www.kompas.com/tren/read/2021/07/14/120300365/ramai-video-sebut-chemtrail-sebar-bahan-kimia-dari-pesawat-ini-faktanya?page=all#page4"><span style="text-decoration: underline;">kompas.com</span></a> yang telah diberitakan sejak Juli 2021, Kepala Dinas Penerbangan TNI Angkatan Udara (Kadispen AU) Marsma TNI Indan Gilang Buldansyah menjelaskan bahwa jejak putih tersebut adalah hal yang wajar.&nbsp;</p><p>“Ini merupakan hasil dari pengembunan udara dengan kadar air tinggi yang bergesekan dengan mesin pesawat. Ada juga yang menyebutnya dengan vapor trails tapi jika bentuknya mulai berpendar atau melebar seperti awan biasa juga disebut dengan aviaticus cloud,” ujar Indan.</p><p>Penjelasan serupa juga disampaikan oleh pengamat penerbangan dan mantan Kepala Staf Angkatan Udara (KSAU), Cheppy Hakim. Ia menekankan bahwa jejak asap yang terlihat di langit merupakan akibat dari proses kondensasi.</p><p>“Intinya karena di atas itu temperaturnya dingin, exhaust knalpotnya itu panas, maka terjadilah proses kondensasi yang terlihat seperti asap putih itu,” kata Cheppy.</p><p>Di sisi lain, Kementerian Kesehatan menegaskan bahwa tuberkulosis (TBC) adalah penyakit menular yang disebabkan oleh bakteri Mycobacterium tuberculosis. Penularannya terjadi melalui droplet atau percikan cairan saat seseorang berbicara, batuk, atau bersin.&nbsp;</p><p>Meskipun TBC paling sering menyerang paru-paru, penyakit ini juga bisa menyebar ke bagian tubuh lain seperti selaput otak, kulit, tulang, hingga kelenjar getah bening.</p><p>TurnBackHoax sejak 2021 juga sudah membantah klaim terkait jejak putih pesawat yang diklaim sebagai chemtrail senjata biologis yang sebabkan Covid-19, seperti yang dilaporkan pada beberapa artikel berikut:</p><ul><li><a href="https://turnbackhoax.id/2021/07/19/salah-chemtrails-penyebar-virus-penyakit-muncul-di-langit-pantura/"><span style="text-decoration: underline;">[SALAH] Chemtrails Penyebar Virus Penyakit Muncul di Langit Pantura</span></a></li><li><a href="https://turnbackhoax.id/2022/02/28/salah-pesawat-kargo-china-yang-mendarat-di-bandara-soetta-tanpa-izin-ternyata-menyebarkan-chemtrail/"><span style="text-decoration: underline;">[SALAH] Pesawat Kargo China Yang Mendarat di Bandara Soetta Tanpa Izin Ternyata Menyebarkan Chemtrail</span></a></li><li><a href="https://turnbackhoax.id/2024/06/30/salah-asap-pesawat-itu-senjata-biologi/"><span style="text-decoration: underline;">[SALAH] “Asap Pesawat Itu Senjata Biologi”</span></a></li></ul><p><strong>Kesimpulan</strong></p><p>Unggahan berisi klaim “ada racun disebarkan dengan chemtrail, sebabkan TBC” merupakan konten yang menyesatkan (misleading content).</p><p><strong><em>(Ditulis oleh Moch. Marcellodiansyah)</em></strong></p>', '2025-06-03 20:58:08', '2025-07-27 21:15:04'),
	(35, '[SALAH] Golkar Dukung Pemakzulan Gibran', 'salah-golkar-dukung-pemakzulan-gibran', 'Pemeriksa Fakta Junior', 3, 'verified', 'nasional', 'https://turnbackhoax.id/2025/05/31/salah-golkar-dukung-pemakzulan-gibran/', 'https://turnbackhoax.id/wp-content/uploads/2025/05/header-gibran-makzulkan-326x245.png', '<ul><li>Tidak ada bukti atau pernyataan resmi yang membenarkan klaim.</li><li>Unggahan berisi klaim “Golkar dukung pemakzulan Gibran” merupakan konten yang menyesatkan (misleading content).</li></ul><p>Kanal YouTube “KajianOnline” pada Rabu (30/4/2025) membagikan <a href="https://www.youtube.com/watch?v=JYwn0uDHsVI"><span style="text-decoration: underline;">video</span></a> [<a href="https://archive.ph/8GVnx/image"><span style="text-decoration: underline;">arsip</span></a>] disertai judul dan sampul (thumbnail) berisi narasi:</p><blockquote>“Pak Jokowi HISTERIS Sampai Masuk RS ! GOLKAR Resmi Dukung Keputusan MPR Soal Pemecatan Gibran !”“Golkar Dukung Pemakzulan Gibran. Jokowi Histeris satu persatu sekutu berkhianat. Prabowo serahkan keputusan ke sidang MPR. Pak Jokowi jatuh sakit sampai masuk RS.”</blockquote><p>Berdasarkan pengamatan Tim Pemeriksa Fakta Mafindo (TurnBackHoax), video yang disertai narasi serupa juga dibagikan oleh akun TikTok “<a href="https://www.tiktok.com/@fak_01berita/video/7506587922766777656"><span style="text-decoration: underline;">fak_01berita</span></a>” [<a href="https://archive.ph/wip/QZ66s"><span style="text-decoration: underline;">arsip</span></a>] pada Rabu (21/5/2025).</p><p>Hingga Sabtu (31/5/2025) unggahan kanal YouTube “KajianOnline” telah disukai oleh 1.700-an pengguna dan menuai 1.000-an komentar. Unggahan TikTok “fak_01berita” telah mendapatkan hampir 12.000 tanda suka dan dikomentari 1.500 kali.</p><p><strong>Pemeriksaan Fakta</strong></p><p>Disadur dari artikel Periksa Fakta <a href="https://tirto.id/hoaks-partai-golkar-mendukung-pemakzulan-gibran-hb2C"><span style="text-decoration: underline;">tirto.id</span></a>.</p><p>Tidak ada bukti atau pernyataan resmi yang membenarkan klaim “Partai Golkar mendukung pemakzulan Gibran”.</p><p>Video hanya menampilkan cuplikan dari Wakil Ketua Umum Partai Golkar, Idrus Marham. Ia memang menanggapi isu pemakzulan Gibran, tetapi tidak ada pernyataan dari Idrus yang menyatakan Partai Golkar mendukung keputusan MPR soal pemakzulan Gibran.</p><p>Menteri Sosial itu justru meyakini Prabowo akan memberi respons terhadap usulan Forum Purnawirawan TNI tersebut dengan pendekatan yang merangkul dan menyatukan.</p><p>Video asli berasal dari unggahan kanal YouTube SINDONews “Idrus Marham soal Surat Purnawirawan: Presiden Bukan Mengacaukan, tapi Menghargai | Sindo Flash” yang tayang April 2025.</p><p>Tidak ada keterangan resmi dari MPR mengenai proses atau rencana pemakzulan Gibran.</p><p>Perlu diketahui, Pasal 7A UUD 1945 menyatakan:</p><p>“Presiden dan/atau Wakil Presiden dapat diberhentikan dalam masa jabatannya oleh Majelis Permusyawaratan Rakyat atas usul Dewan Perwakilan Rakyat, baik apabila terbukti telah melakukan pelanggaran hukum berupa pengkhianatan terhadap negara, korupsi, penyuapan, tindak pidana berat lainnya, atau perbuatan tercela maupun apabila terbukti tidak lagi memenuhi syarat sebagai Presiden dan/atau Wakil Presiden.”</p><p>Lebih lanjut, Pasal 7B ayat (1) UUD 1945 mengatur bahwa:</p><p>“Usul pemberhentian dapat diajukan oleh DPR kepada MPR hanya dengan terlebih dahulu mengajukan permintaan kepada Mahkamah Konstitusi untuk memeriksa, mengadili, dan memutus pendapat DPR bahwa presiden dan/atau wakil presiden telah melakukan pelanggaran hukum berupa pengkhianatan terhadap negara, korupsi, penyuapan, tindak pidana berat lainnya, atau perbuatan tercela; dan/atau pendapat bahwa presiden dan/atau wakil presiden tidak lagi memenuhi syarat sebagai presiden dan/atau wakil presiden.”</p><p>Sebagai informasi, isu pemakzulan Gibran mencuat sejak Kamis (17/4/2025), ketika Forum Purnawirawan Prajurit TNI menggelar pertemuan di Kelapa Gading, Jakarta Utara. Dalam forum itu, delapan tuntutan disampaikan, salah satunya adalah usulan kepada MPR untuk mengganti Wakil Presiden.&nbsp;</p><p>Tuntutan ini dilatarbelakangi oleh anggapan bahwa putusan Mahkamah Konstitusi mengenai Pasal 169 Huruf Q Undang-Undang Pemilu dianggap menyalahi hukum acara dan Undang-Undang Kekuasaan Kehakiman.</p><p><strong>Kesimpulan</strong></p><p>Unggahan berisi klaim “Golkar dukung pemakzulan Gibran” merupakan konten yang menyesatkan (misleading content).</p><p><strong><em>(Ditulis oleh Moch. Marcellodiansyah)</em></strong></p>', '2025-06-03 20:58:09', '2025-07-27 21:14:32'),
	(36, '[PENIPUAN] Tautan Klaim “Bansos Go Digital Kemensos”', 'penipuan-tautan-klaim-bansos-go-digital-kemensos', 'Pemeriksa Fakta Junior', 7, 'verified', 'nasional', 'https://turnbackhoax.id/2025/05/31/penipuan-tautan-klaim-bansos-go-digital-kemensos/', 'https://turnbackhoax.id/wp-content/uploads/2025/05/Header-Bansos-go-digital-326x245.png', '<ul><li>Tautan tidak mengarah ke laman resmi Kemensos, hanya meminta data untuk mengambil alih akun Telegram.</li><li>Unggahan berisi tautan pendaftaran “Bansos Go Digital Kemensos” merupakan konten palsu (fabricated content).</li></ul><p>Akun Facebook “Postingan Seputar Info bantuan terupdate 2025” pada Jumat (16/5/2025) membagikan <a href="https://www.facebook.com/permalink.php?story_fbid=pfbid02ehcfwXLbEb86qxSEy5Eot81wMN9m8L59Fsm9BX49hWcRzoo9bFxZZKHmQUeUZDpUl&amp;id=61573730951212&amp;_rdc=1&amp;_rdr"><span style="text-decoration: underline;">tautan</span></a> [<a href="https://archive.ph/nvE6E"><span style="text-decoration: underline;">arsip</span></a>] pendaftaran Bansos Digital Kemensos.</p><p>Unggahan disertai narasi:</p><blockquote>“📢 BANSOS RESMI KEMENSOS — DAFTAR SEKARANG!&nbsp;💸 Rp1.500.000 Bantuan Tunai Siap Disalurkan!&nbsp;📲 Pendaftaran 100% Online. Tanpa Calo. Tanpa Ribet.&nbsp;🛡️ Resmi dari Kementerian Sosial Republik Indonesia&nbsp;👉 Untuk keluarga yang butuh, bantuannya nyata.&nbsp;👉 Untuk masa depan yang lebih baik, mulai dari sini.&nbsp;✅ Cek Hak Anda. ✅ Daftar Sekarang. ✅ Semua Gratis.”“BANSOS GO DIGITAL. Pendaftaran Bansos Digital Kemensos Telah Dibuka! Bantuan Awal Senilai Rp1.500.000. Daftar sekarang! Pencairan langsung ke rekening dan e-wallet Anda.”</blockquote><p>Hingga Sabtu (31/5/2025) unggahan telah disukai oleh hampir 300 pengguna dan menuai 29 komentar.</p><p><strong>Pemeriksaan Fakta</strong></p><p>Tim Pemeriksa Fakta Mafindo (TurnBackHoax) mengakses tautan dalam unggahan. Tautan tidak mengarah ke laman resmi Kementerian Sosial (Kemensos) <a href="http://kemensos.go.id"><span style="text-decoration: underline;">kemensos.go.id</span></a>.&nbsp;</p><p>Tautan mengarah ke laman pengisian formulir nama lengkap dan nomor telepon, setelah itu pendaftar diminta memasukkan kode OTP yang muncul di aplikasi Telegram.</p><p>Menukil informasi dari Instagram resmi Kemensos, “<a href="https://www.instagram.com/reel/DIqGN5BybF0/"><span style="text-decoration: underline;">kemensosri</span></a>”, Bansos Go Digital merupakan upaya transformasi digital agar bantuan semakin akurat, adil, dan tepat sasaran.</p><p>TurnBackHoax sebelumnya pernah membantah tautan yang diklaim merupakan pendaftaran bansos lewat artikel “<a href="https://turnbackhoax.id/2025/03/27/penipuan-tautan-daftar-bansos-pkh-bpnt-dan-blt-miskin-ekstrem/"><span style="text-decoration: underline;">[PENIPUAN] Tautan Daftar ‘Bansos PKH, BPNT, dan BLT Miskin Ekstrem’</span></a>” yang tayang Maret 2025.</p><p>Penerima bansos merupakan masyarakat yang masuk dalam Data Terpadu Kesejahteraan Sosial (DTKS) terbaru yang dimiliki pemerintah.</p><p>Dilansir dari <a href="https://www.detik.com/sulsel/berita/d-7703547/cara-daftar-bansos-2025-online-lewat-hp"><span style="text-decoration: underline;">detik.com</span></a>, pendaftaran DTKS secara daring dilakukan melalui aplikasi “Cek Bansos”. Untuk pendaftaran luring secara mandiri, sebagaimana dikutip dari <a href="https://indonesiabaik.id/infografis/cara-daftar-dtks-agar-dapat-bantuan-sosial"><span style="text-decoration: underline;">indonesiabaik.id</span></a>, dilakukan dengan datang langsung ke kantor desa/kelurahan setempat, selanjutnya akan ada musyawarah di tingkat desa/kelurahan untuk membahas kondisi kelayakan pendaftar sebagai calon penerima bansos.</p><p><strong>Kesimpulan</strong></p><p>Unggahan berisi tautan pendaftaran “Bansos Go Digital Kemensos” merupakan konten palsu (fabricated content).</p><p><strong><em>(Ditulis oleh Moch. Marcellodiansyah)</em></strong></p>', '2025-06-03 20:58:10', '2025-07-27 21:13:57'),
	(37, '[PENIPUAN] Tautan “Pendaftaran untuk Menjadi Driver Grab”', 'penipuan-tautan-pendaftaran-untuk-menjadi-driver-grab', 'Pemeriksa Fakta Junior', 7, 'verified', 'nasional', 'https://turnbackhoax.id/2025/05/30/penipuan-tautan-pendaftaran-untuk-menjadi-driver-grab/', 'https://turnbackhoax.id/wp-content/uploads/2025/05/HEADER-Dark-Background-2-3-326x245.png', '<ul><li>Faktanya, pendaftaran driver Grab dilakukan dengan mengisi formulir pendaftaran yang ada di aplikasi “Grab Driver”.</li><li>Unggahan berisi tautan “pendaftaran untuk menjadi driver Grab” yang mengarah ke laman tak resmi itu merupakan konten tiruan (impostor content).</li></ul><p>Akun TikTok “Loker Terbaru ” pada Kamis (20/03/2025) membagikan <a href="https://www.tiktok.com/@syaqilah.zr/photo/7483717331026234632?is_from_webapp=1&amp;sender_device=pc&amp;web_id=7505993270243395073"><span style="text-decoration: underline;">foto</span></a> <a href="https://archive.ph/cyKan"><span style="text-decoration: underline;">[arsip]</span></a> mengenai pendaftaran lowongan kerja driver Grab disertai narasi:</p><blockquote>“Lowongan Kerja Driver Grab Terbaru 2025. Pendaftaran gratis raih kesempatan kamu gaji 20jt perbulan, dan berpenghasilan sndri🙌🏻 Cara pendaftaran Silahkan klik web kami !!”</blockquote><p>Informasi pendaftaran silahkan klik web di bio profil</p><p>Per Jumat (30/05/2025), unggahan disukai hampir 500 pengguna dan 122 kali dibagikan ulang.</p><p><strong>Pemeriksaan Fakta</strong></p><p>Tim Pemeriksa Fakta Mafindo (TurnBackHoax) mengakses tautan pendaftaran yang tertera di bio akun. Tautan tidak mengarah ke laman resmi Grab (<a href="https://www.grab.com/id/"><span style="text-decoration: underline;">www.grab.com/id/</span></a>). Warganet justru diminta menuliskan nama lengkap dan nomor telepon yang terhubung dengan Telegram.</p><p>TurnBackHoax kemudian menelusuri laman resmi Grab dan menemukan cara pendaftaran kerja menjadi driver di bagian kolom “<a href="https://www.grab.com/id/driver/drive/"><span style="text-decoration: underline;">Jadilah Mitra Kami</span></a>”. Melansir dari laman resminya, Grab tidak mencantumkan gaji seperti unggahan akun TikTok “Loker Terbaru”.</p><p>Di bagian “alur proses pendaftaran”, Grab menjelaskan pendaftaran driver Grab hanya dilakukan dengan mengisi formulir pendaftaran yang ada di aplikasi “Grab Driver”.</p><p><strong>Kesimpulan</strong></p><p>Unggahan berisi tautan “pendaftaran untuk menjadi driver Grab” yang mengarah ke laman tak resmi itu merupakan konten tiruan (impostor content).</p><p><strong>(</strong><strong><em>Ditulis oleh Amanda Rahma</em></strong><strong>)</strong></p>', '2025-06-03 20:58:12', '2025-07-27 21:13:26'),
	(38, '[SALAH] SPBU di Manado Jual Pertalite Dicampur Air', 'salah-spbu-di-manado-jual-pertalite-dicampur-air', 'Pemeriksa Fakta Junior', 1, 'verified', 'nasional', 'https://turnbackhoax.id/2025/05/30/salah-spbu-di-manado-jual-pertalite-dicampur-air/', 'https://turnbackhoax.id/wp-content/uploads/2025/05/HEADER-Light-Background-6-1-326x245.png', '\n\n\n<ul class="wp-block-list">\n<li>Pihak kepolisian, Pertamina dan disaksikan oleh perwakilan warga sekitar melakukan penyidikan. Hasilnya, BBM berjenis Pertalite yang dijual di SPBU terbukti tidak dicampur air.</li>\n\n\n\n<li>Unggahan berisi klaim “SPBU di Manado menjual Pertalite dicampur air” merupakan konten yang menyesatkan (misleading content).</li>\n</ul>\n\n\n\n<hr class="wp-block-separator has-alpha-channel-opacity">\n\n\n\n<p>Akun Facebook “Sulut Hits” pada Senin (5/5/2025) mengunggah <a href="https://www.facebook.com/reel/692561546798901/?mibextid=rS40aB7S9Ucbxw6v">video</a> [<a href="https://archive.ph/tGDcD">arsip</a>] disertai narasi:</p>\n\n\n\n<blockquote class="wp-block-quote is-layout-flow wp-block-quote-is-layout-flow">\n<p>“Salah Satu SPBU di Kota Manado yang sering Buka 24 jam, Kedapatan Pertalite bercampur Air”</p>\n</blockquote>\n\n\n\n\n\n\n\n<p>Per Jumat (30/5/2025), konten tersebut sudah ditonton 5,5 ribu kali dan disukai lebih dari 38 pengguna.&nbsp;</p>\n\n\n\n<p><span style="background-color: #ff8c00;padding: 3px 8px;font-weight: bold;border-radius: 8px">Pemeriksaan Fakta</span></p>\n\n\n\n<p>Tim Pemeriksa Fakta Mafindo (TurnBackHoax) menelusuri video menggunakan Google Reverse Image. Hasilnya, pencarian mengarah ke video unggahan akun Instagram “<a href="https://www.instagram.com/reel/DJQ1oTdRdQi/?igsh=MTNlM2xybWwwbGdkbg==">sulut_populer</a>”.&nbsp;</p>\n\n\n\n<p>Akun media lokal tersebut pada Senin (5/5/2025) mengunggah konten <a href="https://www.instagram.com/reel/DJRPtBdTVSB/?igsh=YzN1YzIwMDNydmVh">video klarifikasi</a>, isinya memperlihatkan pemeriksaan Pertalite menggunakan pasta air yang disaksikan Kapolsek, pihak Pertamina, dan warga. Setelah dilakukan uji coba, ternyata pasta air tidak berubah warna, itu menandakan Pertalite tidak bercampur dengan air.</p>\n\n\n\n<p>TurnBackHoax kemudian memasukkan kata kunci “SPBU di Manado jual Pertalite dicampur air” ke mesin pencari Google. Terdapat sejumlah artikel yang membahas klaim tersebut, salah satunya dipublikasikan oleh <a href="https://tirto.id/hoaks-spbu-di-manado-jual-pertalite-bercampur-air-hbCu">tirto.id</a> “Hoaks SPBU di Manado Jual Pertalite Bercampur Air” pada Minggu (11/5/2025).</p>\n\n\n\n<p>Berdasarkan artikel tersebut diketahui kalau kabar terkait SPBU di Manado menjual Pertalite dicampur air tidaklah benar. Konteks asli video tersebut hanya memperlihatkan contoh kondisi jika BBM bercampur air.</p>\n\n\n\n<p><span style="background-color: #ff8c00;padding: 3px 8px;font-weight: bold;border-radius: 8px">Kesimpulan</span></p>\n\n\n\n<p>Unggahan berisi klaim “SPBU di Manado menjual Pertalite dicampur air” merupakan konten yang menyesatkan (misleading content).</p>\n\n\n\n<p><strong><em>(Ditulis oleh Amanda Rahma)</em></strong></p>\n\n\n<div class="pagination clear mh-clearfix"> <span class="post-page-numbers current" aria-current="page"><span class="pagelink">1</span></span> <a href="https://turnbackhoax.id/2025/05/30/salah-spbu-di-manado-jual-pertalite-dicampur-air/2/" class="post-page-numbers"><span class="pagelink">2</span></a></div>	', '2025-06-03 20:58:13', '2025-06-03 20:58:13'),
	(39, '[SALAH] Proses Pembuatan Patung Paus Fransiskus dari Emas', 'salah-proses-pembuatan-patung-paus-fransiskus-dari-emas', 'Tim Kalimasada', 4, 'verified', 'nasional', 'https://turnbackhoax.id/2025/05/30/salah-proses-pembuatan-patung-paus-fransiskus-dari-emas/', 'https://turnbackhoax.id/wp-content/uploads/2025/05/4.-Header-Patung-Paus-326x245.png', '<ul><li>Faktanya video pembuatan patung Paus Fransiskus dari emas tersebut merupakan hasil rekayasa kecerdasan buatan (AI).</li><li>Video berisi klaim “proses pembuatan patung Paus Fransiskus dari emas” merupakan konten palsu (fabricated content).</li></ul><p>Beredar <a href="https://www.facebook.com/100076788497591/posts/3874773289454867/"><span style="text-decoration: underline;">video</span></a> [<a href="https://archive.ph/EZY9H"><span style="text-decoration: underline;">arsip</span></a>] dari akun Facebook “Leo Nardo” pada Senin (19/5/2025) yang menampilkan proses pembuatan patung Paus Fransiskus yang terbuat dari emas dengan narasi:</p><blockquote>Patung Bapak paus fransiskus terbuat dari emas murni</blockquote><p>Hingga Jumat (30/5/2025) unggahan tersebut telah ditonton 137 kali dan disukai oleh 14 pengguna Facebook lainnya.</p><p><strong>Pemeriksaan Fakta</strong></p><p>Disadur dari artikel Cek Fakta <a href="https://www.liputan6.com/cek-fakta/read/6031431/cek-fakta-tidak-benar-video-yang-diklaim-proses-pembuatan-patung-emas-paus-fransiskus?page=3"><span style="text-decoration: underline;">liputan6.com</span></a>.</p><p>Cek Fakta Liputan6.com menelusuri kebenaran klaim dengan mengunggah video tersebut ke situs pendeteksi Artificial Intelligence (AI), hive moderation.com.</p><p>Hasilnya, video tersebut diketahui hasil rekayasa Artificial Intelligence (AI) dengan probabilitas 98,5 persen.</p><p>Selain itu, tidak ada media kredibel yang melaporkan kejadian tersebut.</p><p><strong>Kesimpulan</strong></p><p>Video berisi klaim “proses pembuatan patung Paus Fransiskus dari emas” merupakan konten palsu (fabricated content).</p><p><strong><em>(Ditulis oleh Pekik Jalu Utomo)</em></strong></p>', '2025-06-03 20:58:14', '2025-07-27 21:12:33'),
	(40, '[PENIPUAN] Tautan Lowongan Kerja KAI Services', 'penipuan-tautan-lowongan-kerja-kai-services', 'Pemeriksa Fakta Junior', 7, 'verified', 'nasional', 'https://turnbackhoax.id/2025/05/30/penipuan-tautan-lowongan-kerja-kai-services/', 'https://turnbackhoax.id/wp-content/uploads/2025/05/HEADER-Dark-Background-2-2-326x245.png', '<ul><li>Faktanya, lowongan pekerjaan PT Reska Multi Usaha (KAI Services) hanya dapat dilamar melalui laman <a href="https://karir.reska.id/lowongan"><span style="text-decoration: underline;">www.karir.reska.id</span></a>.</li><li>Unggahan berisi tautan “pendaftaran lowongan pekerjaan KAI Services” yang mengarah ke laman tak resmi itu merupakan konten tiruan (impostor content).</li></ul><p>Pada Sabtu (5/4/2025) akun Facebook “Info loker bumn 2025” membagikan <a href="https://www.facebook.com/permalink.php?story_fbid=122121480662717301&amp;id=61571519044354"><span style="text-decoration: underline;">tautan</span></a> [<a href="https://archive.ph/wip/08aow"><span style="text-decoration: underline;">arsip</span></a>] disertai narasi :</p><blockquote>“Lowongan Kerja BUMN PT Reska Multi Usaha (KAI Services)WALK IN INTERVIEWPRAMUGARA DAN PRAMUGARIKualifikasi Umum, Warga Negara Indonesia, Berpenampilan Menarik, Usia 18-40 Tahun, Pendidikan Minimal SMA/Sederajat, etc.”</blockquote><p>Hingga Jumat (16/5/25), unggahan mendapatkan 45 tanda suka dan dibagikan ulang 19 kali.&nbsp;</p><p><strong>Pemeriksaan Fakta</strong></p><p>Tim Pemeriksa Fakta Mafindo (TurnBackHoax) mengakses tautan dalam unggahan. Diketahui, tautan tidak mengarah ke laman resmi PT Reska Multi Usaha (KAI Services) (<a href="https://karir.reska.id/lowongan"><span style="text-decoration: underline;">karir.reska.id</span></a>). Warganet justru diminta menuliskan nama serta nomor handphone yang terhubung dengan akun Telegram.</p><p>Setelah foto unggahan ditelusuri menggunakan Google Lens, diketahui kalau poster serupa pernah diunggah oleh akun LinkedIn resmi “<a href="https://www.linkedin.com/posts/bersamabumn_lowongan-kerja-bumn-pt-reska-multi-usaha-activity-7313768938213969920--07C/"><span style="text-decoration: underline;">Rekrutmen Bersama BUMN</span></a>” yang memiliki lebih dari dua juta pengikut.</p><p>Dalam unggahan aslinya, lowongan kerja hanya mencantumkan kualifikasi pendidikan (minimal SMA/sederajat), tanpa batasan usia dan kriteria “berpenampilan menarik”. Calon pelamar diarahkan untuk mendaftar lewat laman resmi PT Reska Multi Usaha (KAI Services).</p><p>TurnBackHoax kemudian menelusuri informasi lowongan di laman karier KAI Service (<a href="https://karir.reska.id/lowongan"><span style="text-decoration: underline;">karir.reska.id</span></a>). Diketahui, calon pelamar wajib membuat akun, melengkapi data pribadi, memilih posisi yang tersedia, serta mengunggah dokumen persyaratan seperti KTP, ijazah, transkrip nilai, CV, surat lamaran, dan dokumen pendukung lainnya.&nbsp;</p><p>Seluruh informasi mengenai rekrutmen diinformasikan melalui :&nbsp;</p><ul><li><a href="http://karir.reska.id"><span style="text-decoration: underline;">karir.reska.id</span></a></li><li><a href="https://www.facebook.com/RMU.ID?mibextid=D4KYlr"><span style="text-decoration: underline;">Facebook</span></a> “KAI Services”</li><li><a href="https://www.instagram.com/rmu.id/"><span style="text-decoration: underline;">Instagram </span></a>“rmu.id”</li><li><a href="https://twitter.com/RMU_ID?t=cyiaCTrBMMbSGbjFyEUoyg&amp;s=09"><span style="text-decoration: underline;">X</span></a> “RMU_ID”</li><li><a href="https://youtube.com/@kaiservices?si=axY27nC9uHme6N-G"><span style="text-decoration: underline;">YouTube</span></a> “kaiservices”</li></ul><p><strong>Kesimpulan</strong></p><p>Unggahan berisi tautan “pendaftaran lowongan pekerjaan KAI Services” yang mengarah ke laman tak resmi itu merupakan konten tiruan (impostor content).</p><p><strong>(</strong><strong><em>Ditulis oleh Raymondha Elsha</em></strong><strong>)</strong></p>', '2025-06-03 20:58:16', '2025-07-27 21:11:48'),
	(41, '[SALAH] Anak di India Lumpuh Akibat Vaksin Polio Bill Gates', 'salah-anak-di-india-lumpuh-akibat-vaksin-polio-bill-gates', 'Pemeriksa Fakta Junior', 2, 'verified', 'nasional', 'https://turnbackhoax.id/2025/05/30/salah-anak-di-india-lumpuh-akibat-vaksin-polio-bill-gates/', 'https://turnbackhoax.id/wp-content/uploads/2025/05/HEADER-Dark-Background-1-1-326x245.png', '<ul><li>Organisasi Kesehatan Internasional (<a href="https://www.who.int/news-room/spotlight/history-of-vaccination/history-of-polio-vaccination"><span style="text-decoration: underline;">WHO</span></a>) telah menyatakan vaksin polio aman.</li><li>Unggahan berisi klaim “anak di India lumpuh akibat vaksin polio Bill Gates” merupakan konten menyesatkan (misleading content).</li></ul><p>Pada Rabu (14/5/2025) akun Facebook “Al Khansa” membagikan sejumlah <a href="https://www.facebook.com/alkhansa.azzahra2024/posts/122230991690230593"><span style="text-decoration: underline;">foto</span></a> [<a href="https://archive.ph/wip/TB3aX"><span style="text-decoration: underline;">arsip</span></a>] disertai narasi:&nbsp;</p><blockquote>“India menuntut Yayasan Gates ke Pengadilan Ada 47.000 ANAK-ANAK DI INDIA MENDERITA CACAT DAN LUMPUH PERMANEN, AKIBAT LANGSUNG DARI VAKSIN POLIO BILL GATES.<a href="https://envirowatchnz.com/.../47000-children-crippled.../;"><span style="text-decoration: underline;">https://envirowatchnz.com/…/47000-children-crippled…/;</span></a>BELAJARLAH DARI KASUS INDIA INI !”</blockquote><p>Hingga Jumat (30/5/25), unggahan telah mendapatkan 22 tanda suka, 1 komentar dan dibagikan ulang 166 kali.</p><p><strong>Pemeriksaan Fakta</strong></p><p>Disadur dari artikel Cek Fakta <a href="https://www.kompas.com/cekfakta/read/2025/05/16/084900482/-hoaks-47.000-anak-di-india-lumpuh-akibat-vaksin-polio?page=all"><span style="text-decoration: underline;">kompas.com</span></a>.</p><p>Narasi mengenai vaksin polio yang disponsori Bill Gates di India tampaknya berasal dari sebuah laporan yang diterbitkan <a href="https://ijme.in/articles/polio-programme-let-us-declare-victory-and-move-on/?galley=html"><span style="text-decoration: underline;">Indian Journal of Medical Ethics</span></a> pada 2012. Laporan tersebut memuat peningkatan kasus lumpuh layu akut non-polio (NPAFP) yang berbanding lurus dengan dosis polio oral yang diterima.&nbsp;</p><p>Yayasan Gates Foundation mendanai program pemberantasan polio. Kasus NPAFP memang meningkat pada pertengahan 2000-an di India, kendati demikian bukan berarti vaksin polio menjadi penyebab utamanya. <a href="https://www.bbc.com/news/health-21207601"><span style="text-decoration: underline;">BBC News</span></a> melaporkan, polio hanyalah salah satu dari banyak penyebab lumpuh layu akut di India. Virus dan bakteri lain juga ikut memicu peningkatan jumlah kasus.</p><p>Organisasi Kesehatan Internasional (<a href="https://www.who.int/news-room/spotlight/history-of-vaccination/history-of-polio-vaccination"><span style="text-decoration: underline;">WHO</span></a>) telah menyatakan vaksin polio aman dan <a href="https://www.who.int/docs/default-source/biologicals/vaccine-quality/polio-grad-opv-effectiveness.pdf?sfvrsn=9704dc5_2"><span style="text-decoration: underline;">efektif</span></a> menurunkan risiko terjangkit virus.</p><p><strong>Kesimpulan</strong></p><p>Unggahan berisi klaim “anak di India lumpuh akibat vaksin polio Bill Gates” merupakan konten menyesatkan (misleading content).</p><p><strong><em>(Ditulis oleh Raymondha Elsha)</em></strong></p>', '2025-06-03 20:58:17', '2025-07-27 21:11:13');

